RKfill("sql",[{"viz":"sqltable","b":["<b>Basis data</b> adalah kumpulan data yang tersimpan rapi dan bisa dicari dengan cepat. Basis data <b>relasional</b> menyimpan data dalam <b>tabel</b>, mirip lembar kerja spreadsheet. Setiap <b>kolom</b> punya nama dan tipe data, dan setiap <b>baris</b> adalah satu catatan, misalnya satu pelanggan.","Kata \"relasional\" berasal dari hubungan antartabel. Tabel <code>pesanan</code> tidak menyalin nama pelanggan, melainkan menyimpan <code>pelanggan_id</code> yang menunjuk ke tabel <code>pelanggan</code>. Data jadi tidak berulang dan mudah diperbarui.","<b>SQL</b> (Structured Query Language) adalah bahasa untuk berbicara dengan basis data relasional seperti PostgreSQL, MySQL, SQLite, SQL Server, dan Oracle. Di kursus ini kamu memakai <b>Toko Nusantara</b>, database contoh yang berjalan langsung di browser. Coba jalankan query di bawah."],"ex":[["Lihat semua pelanggan","SELECT * FROM pelanggan;"],["Lihat semua produk","SELECT * FROM produk;"],["Pesanan yang sudah masuk","SELECT * FROM pesanan;"]],"task":{"q":"Tampilkan seluruh isi tabel karyawan.","a":"SELECT * FROM karyawan;"},"pts":["Tabel = kumpulan baris dengan kolom yang sama.","Baris = satu catatan (record); kolom = satu atribut (field).","Relasi dibuat dengan menyimpan id tabel lain.","SQL dipakai hampir di semua basis data relasional."],"q":[["Satu pelanggan di tabel pelanggan disimpan sebagai?",["Satu kolom","Satu baris","Satu tabel"],1,"Setiap catatan adalah satu baris."],["Kenapa pesanan menyimpan pelanggan_id, bukan nama pelanggan?",["Supaya lebih panjang","Agar data tidak berulang dan cukup diubah di satu tempat","Karena nama tidak boleh disimpan"],1,"Inilah inti model relasional."]],"so":[{"q":"Tampilkan nama, jabatan, dan divisi semua karyawan.","h":"SELECT kolom1, kolom2 FROM tabel;","a":"SELECT nama, jabatan, divisi FROM karyawan;","out":"nama  | jabatan           | divisi\n------+-------------------+----------\nSari  | Direktur          | Pusat\nTono  | Manajer Gudang    | Gudang\nUmi   | Manajer Penjualan | Penjualan\nVino  | Staf Gudang       | Gudang\nWati  | Staf Gudang       | Gudang\nYudi  | Sales             | Penjualan\nZahra | Sales             | Penjualan\nRio   | Sales             | Penjualan","lang":"sql"},{"q":"Pada tabel produk, sebutkan contoh baris, kolom, primary key, dan sel.","h":"Baris = satu data, kolom = satu atribut.","a":"Baris      : (1, Kopi Gayo, Minuman, 85000, 40) adalah satu produk\nKolom      : nama, kategori, harga, stok\nPrimary key: id, unik untuk setiap produk\nSel        : harga Kopi Gayo = 85000","lang":"text"}]},{"viz":"sqlvsnosql","b":["<b>RDBMS</b> (Relational Database Management System) unggul dalam menjaga kebenaran data. Struktur tabel ditentukan di awal (skema), aturan seperti \"harga harus positif\" dijaga oleh database, dan transaksi menjamin data tidak setengah tersimpan. Bahasa SQL juga standar, sehingga keahlianmu terpakai di banyak sistem.","Batasannya: skema yang kaku perlu diubah lewat migrasi saat kebutuhan berubah, dan menskalakan satu database ke banyak server lebih sulit. Data yang bentuknya sangat bervariasi juga kurang pas di tabel.","Basis data <b>NoSQL</b> menawarkan model lain: dokumen JSON (MongoDB), key-value (Redis), kolom lebar (Cassandra), atau graf (Neo4j). Skemanya lentur dan mudah disebar ke banyak server. Aturan praktis: data transaksi dan relasi yang ketat seperti keuangan dan pesanan memakai SQL; cache, log besar, atau data berbentuk bebas sering memakai NoSQL. Banyak sistem memakai keduanya."],"ex":[["Data relasional: dua tabel dihubungkan id","SELECT p.nama, s.id AS pesanan, s.status\nFROM pelanggan p JOIN pesanan s ON s.pelanggan_id = p.id\nWHERE p.nama = 'Andi';"]],"syn":["MongoDB (NoSQL dokumen)","// Satu dokumen menyimpan pelanggan beserta pesanannya\ndb.pelanggan.insertOne({\n  nama: \"Andi\", kota: \"Jakarta\",\n  pesanan: [\n    { id: 101, status: \"selesai\" },\n    { id: 103, status: \"dikirim\" }\n  ]\n})\ndb.pelanggan.find({ kota: \"Jakarta\" })"],"pts":["RDBMS: skema tetap, aturan data ketat, transaksi ACID, bahasa standar.","NoSQL: skema lentur, mudah diskalakan, model data beragam.","Pilih berdasarkan bentuk data dan kebutuhan konsistensi.","Sistem modern sering memakai keduanya (polyglot persistence)."],"q":[["Untuk sistem pembayaran bank, pilihan yang lebih aman?",["RDBMS","Key-value cache","Tidak pakai database"],0,"Konsistensi dan transaksi sangat penting."],["MongoDB termasuk basis data?",["Relasional","NoSQL dokumen","Graf"],1,"MongoDB menyimpan dokumen mirip JSON."]],"so":[{"q":"Pilih RDBMS atau NoSQL: (a) saldo rekening bank, (b) log klik jutaan per menit, (c) katalog produk dengan atribut sangat beragam, (d) pesanan dengan relasi pelanggan dan produk.","h":"Transaksi ketat dan relasi kuat cocok untuk RDBMS.","a":"(a) RDBMS (ACID)\n(b) NoSQL (wide-column/time series)\n(c) NoSQL dokumen (atau kolom JSON di RDBMS)\n(d) RDBMS","lang":"text"},{"q":"Sebutkan tiga kelebihan SQL dibanding mengolah data di spreadsheet.","h":"Skala, integritas, akses bersama.","a":"1. Sanggup jutaan baris dengan cepat (index).\n2. Aturan data dijaga database (tipe, NOT NULL, foreign key).\n3. Banyak pengguna dan aplikasi bisa mengakses bersamaan dengan hak akses.","lang":"text"}]},{"b":["Perintah SQL disebut <b>statement</b> dan biasanya diakhiri titik koma. Setiap statement disusun dari <b>kata kunci</b> (keyword) seperti <code>SELECT</code>, <code>FROM</code>, <code>WHERE</code>, nama tabel dan kolom, nilai, serta operator.","Kata kunci tidak peka huruf besar-kecil: <code>select</code> sama dengan <code>SELECT</code>. Konvensi umum adalah menulis kata kunci dengan huruf besar agar mudah dibedakan dari nama tabel. Teks (string) diapit <b>kutip tunggal</b>: <code>'Jakarta'</code>. Komentar ditulis dengan <code>--</code> untuk satu baris.","Kata kunci SQL terbagi menjadi beberapa kelompok: <b>DQL</b> untuk membaca data (SELECT), <b>DML</b> untuk mengubah data (INSERT, UPDATE, DELETE), <b>DDL</b> untuk struktur (CREATE, ALTER, DROP), <b>DCL</b> untuk hak akses (GRANT, REVOKE), dan <b>TCL</b> untuk transaksi (BEGIN, COMMIT, ROLLBACK)."],"ex":[["Huruf besar atau kecil sama saja","select nama, kota from pelanggan;"],["Teks diapit kutip tunggal","SELECT nama FROM pelanggan WHERE kota = 'Bandung';"],["Komentar dan beberapa baris","-- produk yang stoknya habis\nSELECT nama, stok\nFROM produk\nWHERE stok = 0;"]],"task":{"q":"Tampilkan kolom nama dan harga dari tabel produk.","a":"SELECT nama, harga FROM produk;"},"pts":["Statement diakhiri titik koma.","Kata kunci tidak peka huruf besar-kecil.","Teks memakai kutip tunggal; kutip ganda untuk nama kolom khusus.","Kelompok perintah: DQL, DML, DDL, DCL, TCL."],"q":[["Cara menulis teks Jakarta di SQL?",["\"Jakarta\"","'Jakarta'","Jakarta"],1,"Kutip tunggal untuk nilai teks."],["CREATE TABLE termasuk kelompok?",["DML","DDL","DCL"],1,"DDL mengatur struktur."]],"so":[{"q":"Tampilkan nama dan kategori produk, lalu urutkan berdasarkan nama.","h":"Kata kunci boleh huruf kecil, tetapi konvensinya huruf besar.","a":"SELECT nama, kategori\nFROM produk\nORDER BY nama;","out":"nama             | kategori\n-----------------+---------\nKacang Mete      | Camilan\nKeripik Singkong | Camilan\nKerupuk Udang    | Camilan\nKopi Gayo        | Minuman\nMadu Hutan       | Minuman\nRendang Kaleng   | Makanan\nSambal Bawang    | Bumbu\nTeh Melati       | Minuman","lang":"sql"},{"q":"Perbaiki query yang salah ini: <code>SELECT nama harga FORM produk</code>","h":"Kolom dipisah koma, dan kata kuncinya FROM.","a":"SELECT nama, harga FROM produk;","out":"nama             | harga\n-----------------+-------\nKopi Gayo        | 85000\nTeh Melati       | 25000\nKeripik Singkong | 15000\nKacang Mete      | 60000\nSambal Bawang    | 30000\nMadu Hutan       | 120000\nRendang Kaleng   | 75000\nKerupuk Udang    | 20000","lang":"sql"}]},{"b":["Setiap kolom punya <b>tipe data</b> yang menentukan nilai apa yang boleh disimpan. Tipe yang paling umum: <code>INTEGER</code> untuk bilangan bulat, <code>DECIMAL(p,s)</code>/<code>NUMERIC</code> untuk angka pecahan yang presisi seperti uang, <code>REAL</code>/<code>FLOAT</code> untuk pecahan perkiraan, <code>VARCHAR(n)</code>/<code>TEXT</code> untuk teks, <code>DATE</code>, <code>TIME</code>, <code>TIMESTAMP</code> untuk waktu, dan <code>BOOLEAN</code>.","Nama tipe sedikit berbeda antar database. PostgreSQL punya <code>SERIAL</code> dan <code>JSONB</code>, MySQL punya <code>TINYINT</code> dan <code>DATETIME</code>. Simulator di kursus ini mengikuti SQLite yang lebih longgar: tipe kolom memberi \"afinitas\", misalnya teks <code>'42'</code> yang dimasukkan ke kolom INTEGER otomatis disimpan sebagai angka.","<code>NULL</code> bukan nol dan bukan teks kosong, melainkan tanda \"nilainya tidak diketahui\". Fungsi <code>typeof</code> dan <code>CAST</code> membantu melihat dan mengubah tipe."],"ex":[["Melihat tipe setiap nilai","SELECT typeof(42), typeof(3.14), typeof('teks'), typeof(NULL);"],["Mengubah tipe dengan CAST","SELECT CAST('125' AS INTEGER) + 5 AS angka,\n       CAST(9.99 AS INTEGER) AS dipotong,\n       CAST(2024 AS TEXT) || '-10' AS teks;"],["Tanggal disimpan sebagai teks berformat ISO","SELECT nama, bergabung FROM pelanggan WHERE bergabung >= '2024-01-01';"]],"task":{"q":"Tampilkan nama produk dan harganya dalam ribuan (harga dibagi 1000, diubah menjadi INTEGER) dengan nama kolom ribu.","a":"SELECT nama, CAST(harga / 1000 AS INTEGER) AS ribu FROM produk;"},"pts":["Pilih tipe sekecil mungkin yang cukup.","Uang: DECIMAL atau INTEGER dalam satuan terkecil, bukan FLOAT.","Tanggal ditulis format ISO: YYYY-MM-DD.","NULL = tidak diketahui, bukan 0."],"q":[["Tipe paling tepat untuk menyimpan harga Rp85.000,50?",["FLOAT","DECIMAL(12,2)","TEXT"],1,"DECIMAL presisi untuk uang."],["Apakah NULL sama dengan 0?",["Ya","Tidak, NULL berarti tidak diketahui","Hanya di kolom angka"],1,"NULL adalah ketiadaan nilai."]],"so":[{"q":"Tampilkan nama produk dan harga setelah PPN 11%, dibulatkan tanpa desimal.","h":"Kalikan dengan 1.11 dan pakai ROUND.","a":"SELECT nama, ROUND(harga * 1.11) AS harga_ppn FROM produk;","out":"nama             | harga_ppn\n-----------------+----------\nKopi Gayo        | 94350\nTeh Melati       | 27750\nKeripik Singkong | 16650\nKacang Mete      | 66600\nSambal Bawang    | 33300\nMadu Hutan       | 133200\nRendang Kaleng   | 83250\nKerupuk Udang    | 22200","lang":"sql"},{"q":"Tampilkan id pesanan dan tahun pesanannya sebagai angka.","h":"EXTRACT(YEAR FROM kolom_tanggal).","a":"SELECT id, EXTRACT(YEAR FROM tanggal) AS tahun FROM pesanan;","out":"id  | tahun\n----+------\n101 | 2024\n102 | 2024\n103 | 2024\n104 | 2024\n105 | 2024\n106 | 2024\n107 | 2024\n108 | 2024\n109 | 2024\n110 | 2024","lang":"sql"}]},{"b":["SQL punya operator <b>aritmetika</b> (<code>+ - * / %</code>), <b>perbandingan</b> (<code>= &lt;&gt; != &lt; &gt; &lt;= &gt;=</code>), <b>logika</b> (<code>AND</code>, <code>OR</code>, <code>NOT</code>), dan penyambung teks <code>||</code> (di MySQL memakai fungsi CONCAT).","Ada juga operator khusus yang sangat sering dipakai: <code>BETWEEN a AND b</code> untuk rentang (termasuk kedua ujung), <code>IN (...)</code> untuk daftar pilihan, <code>LIKE</code> untuk pola teks dengan <code>%</code> (apa saja) dan <code>_</code> (satu karakter), serta <code>IS NULL</code>.","Perhatikan prioritas: <code>AND</code> dikerjakan sebelum <code>OR</code>. Selalu pakai kurung saat mencampur keduanya agar maksudmu jelas. Dan ingat, <code>= NULL</code> tidak pernah benar; gunakan <code>IS NULL</code>."],"ex":[["Aritmetika: nilai stok","SELECT nama, harga, stok, harga * stok AS nilai_stok FROM produk;"],["Perbandingan & logika","SELECT nama, kategori, harga FROM produk\nWHERE (kategori = 'Minuman' OR kategori = 'Camilan') AND harga < 50000;"],["BETWEEN, IN, LIKE","SELECT nama, harga FROM produk\nWHERE harga BETWEEN 20000 AND 90000\n  AND kategori IN ('Minuman', 'Bumbu')\n  AND nama LIKE '%a%';"],["NULL perlu IS NULL","SELECT nama FROM pelanggan WHERE kota IS NULL;"]],"task":{"q":"Tampilkan nama dan harga produk yang namanya diawali huruf K dan harganya kurang dari 50000.","a":"SELECT nama, harga FROM produk WHERE nama LIKE 'K%' AND harga < 50000;"},"pts":["AND sebelum OR; pakai kurung.","BETWEEN termasuk kedua batas.","LIKE: % = apa saja, _ = satu karakter.","NULL dibandingkan dengan IS NULL / IS NOT NULL."],"q":[["<code>nama LIKE 'K_p%'</code> cocok dengan?",["Kopi Gayo","Keripik","Kacang"],0,"K, satu huruf apa saja, p, lalu apa saja."],["Hasil <code>kota = NULL</code> untuk baris yang kotanya kosong?",["TRUE","FALSE","NULL (tidak diketahui), jadi baris tidak terpilih"],2,"Perbandingan dengan NULL menghasilkan NULL."]],"so":[{"q":"Tampilkan produk dengan harga antara 20.000 dan 80.000 yang kategorinya bukan Bumbu.","h":"BETWEEN ... AND ... dan &lt;&gt; atau NOT.","a":"SELECT nama, kategori, harga\nFROM produk\nWHERE harga BETWEEN 20000 AND 80000\n  AND kategori <> 'Bumbu';","out":"nama           | kategori | harga\n---------------+----------+------\nTeh Melati     | Minuman  | 25000\nKacang Mete    | Camilan  | 60000\nRendang Kaleng | Makanan  | 75000\nKerupuk Udang  | Camilan  | 20000","lang":"sql"},{"q":"Tampilkan pelanggan dari Jakarta atau Bandung yang namanya mengandung huruf \"i\".","h":"IN (...) dan LIKE '%i%'.","a":"SELECT nama, kota\nFROM pelanggan\nWHERE kota IN ('Jakarta', 'Bandung')\n  AND nama LIKE '%i%';","out":"nama  | kota\n------+--------\nAndi  | Jakarta\nBudi  | Bandung\nDewi  | Jakarta\nFitri | Bandung","lang":"sql"}]},{"b":["<code>SELECT</code> memilih kolom apa yang ingin ditampilkan, dan <code>FROM</code> menentukan dari tabel mana. <code>SELECT *</code> berarti semua kolom. Di aplikasi sungguhan, sebutkan kolom yang dibutuhkan saja agar data yang dikirim lebih sedikit.","Kolom bisa diberi nama baru dengan <code>AS</code> (alias), dan kamu bisa menampilkan hasil perhitungan, bukan hanya kolom mentah. Tabel juga bisa diberi alias pendek, misalnya <code>FROM produk p</code>, yang sangat berguna saat query melibatkan banyak tabel.","SELECT tidak mengubah data sama sekali. Ia hanya membaca dan menghasilkan tabel hasil (result set). Jadi silakan bereksperimen sebebasnya."],"ex":[["Pilih kolom tertentu","SELECT nama, kategori FROM produk;"],["Alias kolom dan perhitungan","SELECT nama AS produk, harga, harga * 1.11 AS harga_dengan_pajak FROM produk;"],["Alias tabel","SELECT p.nama, p.stok FROM produk AS p;"],["Tanpa tabel: SQL sebagai kalkulator","SELECT 85000 * 3 AS total, 'Toko ' || 'Nusantara' AS nama;"]],"task":{"q":"Tampilkan nama pelanggan dengan alias pembeli, dan kotanya dengan alias asal.","a":"SELECT nama AS pembeli, kota AS asal FROM pelanggan;"},"pts":["SELECT = kolom apa, FROM = tabel mana.","Hindari SELECT * di aplikasi produksi.","AS memberi alias kolom atau tabel.","SELECT hanya membaca, tidak mengubah data."],"q":[["Query yang menampilkan semua kolom tabel produk?",["SELECT ALL produk;","SELECT * FROM produk;","GET produk;"],1,"Bintang berarti semua kolom."],["Fungsi AS di <code>SELECT harga AS h</code>?",["Mengubah nama kolom di tabel","Memberi nama kolom di hasil saja","Menyaring data"],1,"Alias hanya berlaku di hasil query."]],"so":[{"q":"Tampilkan nama produk sebagai \"produk\" dan harga per 100 gram sebagai \"harga_per_100g\" (anggap tiap produk 250 gram).","h":"Alias dengan AS; harga * 100 / 250.","a":"SELECT nama AS produk, harga * 100 / 250 AS harga_per_100g FROM produk;","out":"produk           | harga_per_100g\n-----------------+---------------\nKopi Gayo        | 34000\nTeh Melati       | 10000\nKeripik Singkong | 6000\nKacang Mete      | 24000\nSambal Bawang    | 12000\nMadu Hutan       | 48000\nRendang Kaleng   | 30000\nKerupuk Udang    | 8000","lang":"sql"},{"q":"Tampilkan label \"Nama (Kota)\" untuk setiap pelanggan dalam satu kolom bernama label. Apa yang terjadi pada pelanggan yang kotanya kosong?","h":"Gabungkan teks dengan ||. Menggabungkan dengan NULL menghasilkan NULL; pakai COALESCE jika ingin teks pengganti.","a":"SELECT nama || ' (' || kota || ')' AS label FROM pelanggan;","out":"label\n-----------------\nAndi (Jakarta)\nBudi (Bandung)\nCitra (Surabaya)\nDewi (Jakarta)\nEko (Medan)\nFitri (Bandung)\nNULL\nHadi (Yogyakarta)","lang":"sql"}],"pro":[{"t":"Sebutkan kolom yang dibutuhkan","tag":"Best practice","why":"<code>SELECT *</code> praktis saat menjelajah, tetapi di aplikasi sebaiknya kolom disebutkan. Data yang dikirim lebih sedikit, dan query tidak berubah perilaku diam-diam saat tabel mendapat kolom baru.","lang":"sql","a":"SELECT * FROM produk ORDER BY harga DESC LIMIT 3;","b":"SELECT nama, harga FROM produk ORDER BY harga DESC LIMIT 3;","outA":"id | nama           | kategori | harga  | stok\n---+----------------+----------+--------+-----\n6  | Madu Hutan     | Minuman  | 120000 | 15\n1  | Kopi Gayo      | Minuman  | 85000  | 40\n7  | Rendang Kaleng | Makanan  | 75000  | 0","outB":"nama           | harga\n---------------+-------\nMadu Hutan     | 120000\nKopi Gayo      | 85000\nRendang Kaleng | 75000"}]},{"viz":"pipeline","vq":"SELECT nama, kota FROM pelanggan WHERE kota = 'Jakarta' OR kota = 'Bandung';","b":["<code>WHERE</code> menyaring baris: hanya baris yang kondisinya bernilai benar yang ikut ke hasil. Bayangkan database memeriksa setiap baris satu per satu, lalu membuang yang tidak memenuhi syarat. Visualisasi di bawah memperlihatkan proses itu.","Kondisi bisa digabung dengan <code>AND</code> dan <code>OR</code>, dan memakai operator seperti <code>IN</code>, <code>BETWEEN</code>, <code>LIKE</code>, serta <code>IS NULL</code>. Untuk teks, perbandingan biasanya peka huruf besar-kecil di PostgreSQL tetapi tidak di MySQL.","WHERE hanya bisa memakai nilai dari baris yang sedang diperiksa. Ia tidak bisa memakai hasil COUNT atau SUM, karena pengelompokan belum terjadi pada tahap ini. Untuk itu ada HAVING."],"ex":[["Satu kondisi","SELECT nama, harga FROM produk WHERE kategori = 'Camilan';"],["Beberapa kondisi","SELECT nama, stok FROM produk WHERE stok < 50 AND harga > 50000;"],["IN dan NOT IN","SELECT nama, kota FROM pelanggan WHERE kota NOT IN ('Jakarta', 'Bandung');"],["Rentang tanggal","SELECT id, tanggal, status FROM pesanan WHERE tanggal BETWEEN '2024-10-01' AND '2024-10-31';"]],"task":{"q":"Tampilkan id dan status pesanan yang statusnya selesai atau dikirim, dan terjadi pada bulan November 2024.","a":"SELECT id, status FROM pesanan WHERE status IN ('selesai','dikirim') AND tanggal >= '2024-11-01' AND tanggal < '2024-12-01';"},"pts":["WHERE memeriksa setiap baris satu per satu.","Gabungkan kondisi dengan AND/OR dan kurung.","Rentang tanggal: <code>&gt;= awal AND &lt; awal_bulan_berikutnya</code> aman untuk timestamp.","Agregat tidak boleh di WHERE."],"q":[["Baris yang kondisinya NULL di WHERE?",["Ikut","Dibuang","Error"],1,"Hanya kondisi TRUE yang lolos."],["Cara menyaring kategori Minuman atau Bumbu yang paling ringkas?",["kategori = 'Minuman' AND 'Bumbu'","kategori IN ('Minuman','Bumbu')","kategori LIKE 'Minuman,Bumbu'"],1,"IN memeriksa daftar pilihan."]],"so":[{"q":"Tampilkan pelanggan yang kotanya belum diisi.","h":"Pakai IS NULL, bukan = NULL.","a":"SELECT id, nama FROM pelanggan WHERE kota IS NULL;","out":"id | nama\n---+-----\n7  | Gita","lang":"sql"},{"q":"Tampilkan produk yang stoknya habis atau harganya di atas 100.000.","h":"Gabungkan kondisi dengan OR.","a":"SELECT nama, harga, stok FROM produk WHERE stok = 0 OR harga > 100000;","out":"nama           | harga  | stok\n---------------+--------+-----\nMadu Hutan     | 120000 | 15\nRendang Kaleng | 75000  | 0","lang":"sql"}],"pro":[{"t":"Rentang dan daftar nilai","tag":"Lebih mudah dibaca","why":"<code>BETWEEN</code> mencakup kedua batas, dan <code>IN</code> menggantikan rangkaian <code>OR</code>. Hasilnya sama, tetapi maksud query langsung terbaca.","lang":"sql","a":"SELECT nama, kategori, harga\nFROM produk\nWHERE harga >= 10000 AND harga <= 30000\n  AND (kategori = 'Camilan' OR kategori = 'Minuman')\nORDER BY harga;","b":"SELECT nama, kategori, harga\nFROM produk\nWHERE harga BETWEEN 10000 AND 30000\n  AND kategori IN ('Camilan', 'Minuman')\nORDER BY harga;","out":"nama             | kategori | harga\n-----------------+----------+------\nKeripik Singkong | Camilan  | 15000\nKerupuk Udang    | Camilan  | 20000\nTeh Melati       | Minuman  | 25000"}]},{"b":["<code>ORDER BY</code> mengurutkan hasil. Default-nya naik (<code>ASC</code>), tambahkan <code>DESC</code> untuk turun. Kamu bisa mengurutkan dengan beberapa kolom: kolom kedua dipakai ketika nilai kolom pertama sama. Tanpa ORDER BY, urutan hasil tidak dijamin.","<code>LIMIT n</code> membatasi jumlah baris, dan <code>OFFSET m</code> melewati m baris pertama. Pasangan ini dipakai untuk \"10 produk termahal\" atau paginasi halaman 2, 3, dan seterusnya. SQL Server memakai <code>TOP n</code> atau <code>OFFSET ... FETCH</code>.","<code>DISTINCT</code> membuang baris hasil yang kembar, misalnya untuk melihat daftar kota tanpa pengulangan."],"ex":[["Termahal ke termurah","SELECT nama, harga FROM produk ORDER BY harga DESC;"],["Urut dua kolom","SELECT nama, kategori, harga FROM produk ORDER BY kategori, harga DESC;"],["Tiga teratas","SELECT nama, stok FROM produk ORDER BY stok DESC LIMIT 3;"],["Halaman kedua (2 per halaman)","SELECT id, nama FROM pelanggan ORDER BY id LIMIT 2 OFFSET 2;"],["Kota tanpa duplikat","SELECT DISTINCT kota FROM pelanggan ORDER BY kota;"]],"task":{"q":"Tampilkan nama dan tanggal bergabung dari 3 pelanggan yang paling baru bergabung, urut dari yang terbaru.","a":"SELECT nama, bergabung FROM pelanggan ORDER BY bergabung DESC LIMIT 3;","order":true},"pts":["ASC naik (default), DESC turun.","Tanpa ORDER BY, urutan tidak dijamin.","LIMIT/OFFSET untuk top-N dan paginasi.","DISTINCT membuang baris kembar."],"q":[["Mengambil 5 produk termurah?",["ORDER BY harga DESC LIMIT 5","ORDER BY harga LIMIT 5","LIMIT 5 ORDER BY harga"],1,"Urut naik lalu batasi."],["Di mana NULL muncul saat ORDER BY ASC di SQLite?",["Paling atas","Paling bawah","Dibuang"],0,"SQLite dan MySQL menaruh NULL di awal untuk ASC; PostgreSQL di akhir."]],"so":[{"q":"Tampilkan 3 produk dengan stok terbanyak.","h":"ORDER BY stok DESC lalu LIMIT 3.","a":"SELECT nama, stok FROM produk ORDER BY stok DESC LIMIT 3;","out":"nama             | stok\n-----------------+-----\nKeripik Singkong | 200\nKerupuk Udang    | 150\nTeh Melati       | 120","lang":"sql"},{"q":"Tampilkan daftar kota pelanggan tanpa duplikat dan tanpa NULL, urut abjad.","h":"DISTINCT, WHERE ... IS NOT NULL, ORDER BY.","a":"SELECT DISTINCT kota FROM pelanggan WHERE kota IS NOT NULL ORDER BY kota;","out":"kota\n----------\nBandung\nJakarta\nMedan\nSurabaya\nYogyakarta","lang":"sql"}]},{"viz":"pipeline","vq":"SELECT kategori, COUNT(*) AS jumlah, AVG(harga) AS rata FROM produk WHERE stok > 0 GROUP BY kategori HAVING COUNT(*) >= 2 ORDER BY rata DESC LIMIT 2;","b":["Query ditulis dimulai dari SELECT, tetapi database tidak menjalankannya dari SELECT. Urutan logisnya: <b>FROM</b> (ambil tabel dan gabungan), <b>WHERE</b> (saring baris), <b>GROUP BY</b> (kelompokkan), <b>HAVING</b> (saring kelompok), <b>SELECT</b> (hitung kolom hasil), <b>DISTINCT</b>, <b>ORDER BY</b> (urutkan), lalu <b>LIMIT</b>.","Urutan ini menjelaskan banyak \"keanehan\". Alias yang dibuat di SELECT tidak bisa dipakai di WHERE, karena WHERE berjalan lebih dulu. Sebaliknya, ORDER BY boleh memakai alias karena berjalan setelah SELECT.","Putar visualisasi di bawah langkah demi langkah. Di setiap pelajaran SQL berikutnya, tombol <b>Jelaskan langkah</b> di editor juga bisa memvisualisasikan query buatanmu sendiri."],"ex":[["Query lengkap dengan semua klausa","SELECT kategori, COUNT(*) AS jumlah, AVG(harga) AS rata\nFROM produk\nWHERE stok > 0\nGROUP BY kategori\nHAVING COUNT(*) >= 2\nORDER BY rata DESC\nLIMIT 2;"],["Alias di ORDER BY boleh","SELECT nama, harga * stok AS nilai FROM produk ORDER BY nilai DESC;"]],"task":{"q":"Tampilkan nama dan nilai stok (harga * stok, alias nilai) untuk produk yang stoknya lebih dari 0, urut dari nilai terbesar.","a":"SELECT nama, harga * stok AS nilai FROM produk WHERE stok > 0 ORDER BY nilai DESC;","order":true},"pts":["Urutan: FROM → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT.","Alias SELECT tidak bisa dipakai di WHERE (di kebanyakan database).","ORDER BY bisa memakai alias.","Pahami urutan ini untuk membaca query rumit."],"q":[["Klausa yang dijalankan paling awal?",["SELECT","FROM","WHERE"],1,"Database harus tahu dulu tabel sumbernya."],["Kenapa <code>WHERE nilai &gt; 100</code> gagal jika nilai adalah alias di SELECT?",["Typo","WHERE berjalan sebelum SELECT membuat alias","Alias harus huruf besar"],1,"Pada tahap WHERE, alias belum ada."]],"so":[{"q":"Urutkan cara database menjalankan klausa: SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY, LIMIT.","h":"Database mulai dari tabel sumber, bukan dari SELECT.","a":"FROM -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY -> LIMIT","lang":"text"},{"q":"Kenapa <code>WHERE nilai &gt; 1000000</code> gagal jika nilai adalah alias di SELECT? Tulis versi yang benar.","h":"WHERE dijalankan sebelum SELECT, jadi alias belum ada. Ulangi ekspresinya.","a":"SELECT nama, harga * stok AS nilai\nFROM produk\nWHERE harga * stok > 1000000\nORDER BY nilai DESC;","out":"nama             | nilai\n-----------------+--------\nKopi Gayo        | 3400000\nTeh Melati       | 3000000\nKeripik Singkong | 3000000\nKerupuk Udang    | 3000000\nSambal Bawang    | 2400000\nKacang Mete      | 2100000\nMadu Hutan       | 1800000","lang":"sql"}]},{"b":["Manajer toko meminta beberapa daftar untuk katalog cetak. Kerjakan tantangan berurutan; setiap tantangan dinilai otomatis dan progresnya tersimpan."],"ex":[["Lihat produk","SELECT * FROM produk;"]],"tasks":[{"q":"Tampilkan nama dan harga semua produk kategori Camilan, urut dari harga termurah.","a":"SELECT nama, harga FROM produk WHERE kategori = 'Camilan' ORDER BY harga;","order":true},{"q":"Tampilkan 3 produk termahal (nama, harga).","a":"SELECT nama, harga FROM produk ORDER BY harga DESC LIMIT 3;","order":true},{"q":"Tampilkan daftar kategori tanpa duplikat, urut abjad.","a":"SELECT DISTINCT kategori FROM produk ORDER BY kategori;","order":true},{"q":"Tampilkan nama produk yang stoknya kurang dari 50 tetapi tidak habis (stok > 0).","a":"SELECT nama FROM produk WHERE stok < 50 AND stok > 0;"}],"pts":[],"q":[]},{"b":["<code>INSERT INTO tabel (kolom, ...) VALUES (nilai, ...)</code> menambah baris baru. Sebutkan nama kolom secara eksplisit: urutan nilai mengikuti urutan kolom yang kamu tulis, dan kolom yang tidak disebut akan memakai nilai <code>DEFAULT</code> atau NULL.","Satu INSERT bisa menambah banyak baris sekaligus dengan beberapa kelompok VALUES yang dipisah koma. Kamu juga bisa menyalin hasil query ke tabel lain dengan <code>INSERT INTO ... SELECT ...</code>.","Kolom <code>id INTEGER PRIMARY KEY</code> terisi otomatis jika dikosongkan. Di PostgreSQL ini disebut SERIAL/IDENTITY, di MySQL AUTO_INCREMENT. Database akan menolak data yang melanggar aturan tabel, misalnya NOT NULL atau CHECK."],"ex":[["Tambah satu produk","INSERT INTO produk (nama, kategori, harga, stok)\nVALUES ('Gula Aren', 'Bumbu', 18000, 60);\nSELECT * FROM produk WHERE nama = 'Gula Aren';"],["Tambah beberapa baris sekaligus","INSERT INTO pelanggan (nama, kota, bergabung) VALUES\n  ('Indra', 'Makassar', '2024-10-01'),\n  ('Joko', 'Semarang', '2024-10-05');\nSELECT * FROM pelanggan ORDER BY id DESC LIMIT 2;"],["Ditolak: nama wajib diisi","INSERT INTO produk (kategori, harga) VALUES ('Minuman', 10000);"]],"task":{"q":"Tambahkan pelanggan baru bernama Kiki dari Malang yang bergabung tanggal 2024-11-20.","a":"INSERT INTO pelanggan (nama, kota, bergabung) VALUES ('Kiki', 'Malang', '2024-11-20');","check":"SELECT nama, kota, bergabung FROM pelanggan ORDER BY id;"},"pts":["Selalu sebutkan daftar kolom.","Kolom yang tidak disebut memakai DEFAULT/NULL.","Banyak baris: VALUES (...), (...).","<code>INSERT INTO ... SELECT</code> menyalin data."],"q":[["Kolom stok tidak disebut saat INSERT dan punya DEFAULT 0. Nilainya?",["NULL","0","Error"],1,"DEFAULT dipakai."],["Kenapa sebaiknya menyebut nama kolom di INSERT?",["Wajib di semua database","Agar tidak rusak jika urutan atau jumlah kolom tabel berubah","Lebih cepat"],1,"Query jadi tahan perubahan skema."]],"so":[{"q":"Tambahkan dua produk sekaligus: Gula Aren (Bumbu, 22.000, stok 60) dan Kopi Toraja (Minuman, 95.000, stok 25), lalu tampilkan produk id 9 dan 10.","h":"Satu INSERT dengan beberapa kelompok VALUES.","a":"INSERT INTO produk (id, nama, kategori, harga, stok) VALUES\n  (9, 'Gula Aren', 'Bumbu', 22000, 60),\n  (10, 'Kopi Toraja', 'Minuman', 95000, 25);\nSELECT id, nama, harga FROM produk WHERE id >= 9;","out":"id | nama        | harga\n---+-------------+------\n9  | Gula Aren   | 22000\n10 | Kopi Toraja | 95000","lang":"sql"},{"q":"Tambahkan pesanan baru id 120 untuk pelanggan 5 tanggal 2024-12-01 tanpa menyebut status, lalu lihat status bawaannya.","h":"Kolom yang tidak diisi memakai DEFAULT.","a":"INSERT INTO pesanan (id, pelanggan_id, tanggal) VALUES (120, 5, '2024-12-01');\nSELECT id, status FROM pesanan WHERE id = 120;","out":"id  | status\n----+-------\n120 | baru","lang":"sql"}]},{"b":["<code>UPDATE tabel SET kolom = nilai WHERE kondisi</code> mengubah baris yang memenuhi kondisi. Nilai baru boleh berupa rumus dari nilai lama, misalnya menaikkan harga 10%: <code>SET harga = harga * 1.1</code>.","<code>DELETE FROM tabel WHERE kondisi</code> menghapus baris. <b>Peringatan terbesar di SQL</b>: tanpa WHERE, UPDATE dan DELETE mengenai <i>semua</i> baris. Kebiasaan aman: jalankan dulu <code>SELECT</code> dengan WHERE yang sama untuk melihat baris mana yang akan terkena, baru ubah menjadi UPDATE atau DELETE.","Database juga menjaga relasi. Menghapus pelanggan yang masih punya pesanan akan ditolak oleh foreign key, kecuali tabelnya dibuat dengan <code>ON DELETE CASCADE</code>."],"ex":[["Cek dulu dengan SELECT","SELECT nama, harga FROM produk WHERE kategori = 'Minuman';"],["Lalu UPDATE","UPDATE produk SET harga = harga + 5000 WHERE kategori = 'Minuman';\nSELECT nama, harga FROM produk WHERE kategori = 'Minuman';"],["Ubah beberapa kolom","UPDATE pesanan SET status = 'selesai' WHERE id = 107;\nSELECT * FROM pesanan WHERE id = 107;"],["DELETE yang ditolak foreign key","DELETE FROM pelanggan WHERE id = 1;"],["DELETE yang aman","DELETE FROM detail_pesanan WHERE pesanan_id = 105;\nSELECT COUNT(*) AS sisa FROM detail_pesanan;"]],"task":{"q":"Ubah stok produk Rendang Kaleng menjadi 25.","a":"UPDATE produk SET stok = 25 WHERE nama = 'Rendang Kaleng';","check":"SELECT nama, stok FROM produk ORDER BY id;"},"pts":["Selalu tulis WHERE pada UPDATE dan DELETE.","Uji dengan SELECT sebelum mengubah.","Nilai baru boleh rumus dari nilai lama.","Foreign key melindungi data yang masih dirujuk."],"q":[["<code>DELETE FROM produk;</code> tanpa WHERE akan?",["Menghapus tabel","Menghapus semua baris","Error"],1,"Struktur tetap, semua baris hilang."],["Kebiasaan aman sebelum UPDATE?",["Matikan komputer","Jalankan SELECT dengan WHERE yang sama","Hapus index"],1,"Pastikan baris yang terkena benar."]],"so":[{"q":"Naikkan harga semua produk kategori Minuman sebesar 10%, lalu tampilkan hasilnya.","h":"UPDATE ... SET harga = ROUND(harga * 1.1) WHERE ... (dibulatkan agar tidak ada sisa desimal).","a":"UPDATE produk SET harga = ROUND(harga * 1.1) WHERE kategori = 'Minuman';\nSELECT nama, harga FROM produk WHERE kategori = 'Minuman';","out":"nama       | harga\n-----------+-------\nKopi Gayo  | 93500\nTeh Melati | 27500\nMadu Hutan | 132000","lang":"sql"},{"q":"Hapus semua pesanan berstatus batal beserta detailnya, lalu hitung sisa pesanan.","h":"Hapus dulu baris anak (detail_pesanan) agar foreign key tidak dilanggar.","a":"DELETE FROM detail_pesanan\nWHERE pesanan_id IN (SELECT id FROM pesanan WHERE status = 'batal');\nDELETE FROM pesanan WHERE status = 'batal';\nSELECT COUNT(*) AS sisa FROM pesanan;","out":"sisa\n----\n9","lang":"sql"}]},{"b":["<b>Fungsi agregat</b> merangkum banyak baris menjadi satu nilai. <code>COUNT</code> menghitung, <code>SUM</code> menjumlah, <code>AVG</code> merata-rata, <code>MIN</code> dan <code>MAX</code> mencari nilai terkecil dan terbesar.","Perbedaan penting: <code>COUNT(*)</code> menghitung semua baris, sedangkan <code>COUNT(kolom)</code> hanya menghitung baris yang kolom itu tidak NULL. <code>COUNT(DISTINCT kolom)</code> menghitung nilai yang berbeda saja.","Semua fungsi agregat selain COUNT(*) mengabaikan NULL. Jadi AVG dari (10, NULL, 20) adalah 15, bukan 10."],"ex":[["Ringkasan produk","SELECT COUNT(*) AS jumlah, SUM(stok) AS total_stok, AVG(harga) AS rata,\n       MIN(harga) AS termurah, MAX(harga) AS termahal\nFROM produk;"],["COUNT(*) vs COUNT(kolom)","SELECT COUNT(*) AS semua, COUNT(kota) AS ada_kota, COUNT(DISTINCT kota) AS kota_berbeda FROM pelanggan;"],["Agregat dengan WHERE","SELECT SUM(jumlah) AS kopi_terjual FROM detail_pesanan WHERE produk_id = 1;"]],"task":{"q":"Hitung jumlah pesanan yang statusnya selesai (satu kolom bernama jumlah).","a":"SELECT COUNT(*) AS jumlah FROM pesanan WHERE status = 'selesai';"},"pts":["COUNT, SUM, AVG, MIN, MAX merangkum banyak baris.","COUNT(*) semua baris; COUNT(kolom) hanya yang tidak NULL.","Agregat mengabaikan NULL.","WHERE dijalankan sebelum agregasi."],"q":[["<code>COUNT(kota)</code> jika 1 dari 8 pelanggan kotanya NULL?",["8","7","1"],1,"NULL tidak dihitung."],["Fungsi untuk rata-rata?",["MEAN","AVG","AVERAGE"],1,"AVG adalah nama standar SQL."]],"so":[{"q":"Hitung jumlah pelanggan, jumlah kota berbeda, dan tanggal bergabung paling awal.","h":"COUNT(*), COUNT(DISTINCT ...), MIN.","a":"SELECT COUNT(*) AS pelanggan,\n       COUNT(DISTINCT kota) AS kota,\n       MIN(bergabung) AS pertama\nFROM pelanggan;","out":"pelanggan | kota | pertama\n----------+------+-----------\n8         | 5    | 2023-01-15","lang":"sql"},{"q":"Hitung rata-rata harga produk Camilan, dibulatkan tanpa desimal.","h":"AVG dengan WHERE, lalu ROUND.","a":"SELECT ROUND(AVG(harga)) AS rata_camilan FROM produk WHERE kategori = 'Camilan';","out":"rata_camilan\n------------\n31667","lang":"sql"}]},{"viz":"pipeline","vq":"SELECT kategori, COUNT(*) AS jumlah, SUM(stok) AS total_stok FROM produk GROUP BY kategori;","b":["<code>GROUP BY</code> membagi baris menjadi kelompok berdasarkan nilai kolom tertentu, lalu fungsi agregat dihitung <i>per kelompok</i>. Misalnya jumlah produk per kategori, atau total belanja per pelanggan.","Aturan emas: setiap kolom di SELECT harus berupa kolom yang ada di GROUP BY, atau dibungkus fungsi agregat. PostgreSQL menolak query yang melanggar aturan ini, sedangkan SQLite dan MySQL lama diam-diam mengambil nilai dari baris sembarang. Jangan bergantung pada perilaku itu.","Kamu bisa mengelompokkan berdasarkan beberapa kolom, atau berdasarkan ekspresi seperti bulan dari tanggal."],"ex":[["Jumlah produk per kategori","SELECT kategori, COUNT(*) AS jumlah, SUM(stok) AS total_stok\nFROM produk GROUP BY kategori;"],["Pesanan per pelanggan","SELECT pelanggan_id, COUNT(*) AS banyak_pesanan\nFROM pesanan GROUP BY pelanggan_id ORDER BY banyak_pesanan DESC;"],["Per bulan","SELECT strftime('%Y-%m', tanggal) AS bulan, COUNT(*) AS pesanan\nFROM pesanan GROUP BY bulan ORDER BY bulan;"],["Dua kolom","SELECT pelanggan_id, status, COUNT(*) AS n FROM pesanan\nGROUP BY pelanggan_id, status ORDER BY pelanggan_id;"]],"task":{"q":"Tampilkan setiap status pesanan beserta banyaknya pesanan (kolom status dan jumlah).","a":"SELECT status, COUNT(*) AS jumlah FROM pesanan GROUP BY status;"},"pts":["GROUP BY = satu baris hasil per kelompok.","Kolom SELECT: ada di GROUP BY atau di dalam agregat.","Boleh mengelompokkan dengan ekspresi.","ORDER BY tetap diperlukan untuk urutan."],"q":[["<code>SELECT kategori, nama, COUNT(*) FROM produk GROUP BY kategori</code> bermasalah karena?",["COUNT salah","nama tidak di GROUP BY dan tidak diagregasi","kategori harus di akhir"],1,"Satu kategori punya banyak nama."],["Jumlah baris hasil GROUP BY kategori jika ada 4 kategori?",["4","8","1"],0,"Satu baris per kelompok."]],"so":[{"q":"Tampilkan jumlah karyawan dan total gaji per divisi, urut dari total gaji terbesar.","h":"GROUP BY divisi dengan COUNT dan SUM.","a":"SELECT divisi, COUNT(*) AS orang, SUM(gaji) AS total_gaji\nFROM karyawan\nGROUP BY divisi\nORDER BY total_gaji DESC;","out":"divisi    | orang | total_gaji\n----------+-------+-----------\nPenjualan | 4     | 40500000\nPusat     | 1     | 30000000\nGudang    | 3     | 29500000","lang":"sql"},{"q":"Tampilkan jumlah pelanggan per kota, termasuk yang kotanya kosong.","h":"NULL menjadi satu kelompok sendiri.","a":"SELECT kota, COUNT(*) AS n FROM pelanggan GROUP BY kota ORDER BY n DESC, kota;","out":"kota       | n\n-----------+--\nBandung    | 2\nJakarta    | 2\nNULL       | 1\nMedan      | 1\nSurabaya   | 1\nYogyakarta | 1","lang":"sql"}]},{"viz":"pipeline","vq":"SELECT pelanggan_id, COUNT(*) AS banyak FROM pesanan GROUP BY pelanggan_id HAVING COUNT(*) >= 2;","b":["<code>HAVING</code> menyaring <b>kelompok</b>, sedangkan WHERE menyaring <b>baris</b>. Karena HAVING berjalan setelah GROUP BY, ia boleh memakai fungsi agregat: \"tampilkan pelanggan yang pesanannya lebih dari 1\".","Satu query bisa memakai keduanya. WHERE membuang baris yang tidak relevan lebih dulu (misalnya pesanan batal), lalu GROUP BY mengelompokkan, lalu HAVING membuang kelompok yang tidak memenuhi syarat.","Pakai WHERE kapan pun memungkinkan, karena menyaring lebih awal berarti lebih sedikit data yang harus dikelompokkan."],"ex":[["Pelanggan dengan minimal 2 pesanan","SELECT pelanggan_id, COUNT(*) AS banyak\nFROM pesanan GROUP BY pelanggan_id\nHAVING COUNT(*) >= 2;"],["WHERE dan HAVING bersama","SELECT pelanggan_id, COUNT(*) AS selesai\nFROM pesanan\nWHERE status = 'selesai'\nGROUP BY pelanggan_id\nHAVING COUNT(*) >= 2;"],["Kategori dengan rata-rata harga di atas 50 ribu","SELECT kategori, AVG(harga) AS rata FROM produk\nGROUP BY kategori HAVING AVG(harga) > 50000;"],["Salah: agregat di WHERE","SELECT kategori FROM produk WHERE COUNT(*) > 1 GROUP BY kategori;"]],"task":{"q":"Tampilkan produk_id dan total jumlah terjual (alias total) untuk produk yang total terjualnya minimal 5, dari tabel detail_pesanan.","a":"SELECT produk_id, SUM(jumlah) AS total FROM detail_pesanan GROUP BY produk_id HAVING SUM(jumlah) >= 5;"},"pts":["WHERE menyaring baris, HAVING menyaring kelompok.","HAVING boleh memakai agregat.","Urutan: WHERE → GROUP BY → HAVING.","Saring sedini mungkin dengan WHERE."],"q":[["Untuk \"kategori yang punya lebih dari 2 produk\" pakai?",["WHERE COUNT(*) > 2","HAVING COUNT(*) > 2","ORDER BY COUNT(*)"],1,"Syarat atas kelompok memakai HAVING."],["Mana yang dijalankan lebih dulu?",["HAVING","WHERE","Sama"],1,"WHERE sebelum GROUP BY, HAVING sesudahnya."]],"so":[{"q":"Tampilkan divisi yang rata-rata gajinya di atas 10 juta.","h":"Kondisi pada hasil agregat memakai HAVING.","a":"SELECT divisi, AVG(gaji) AS rata\nFROM karyawan\nGROUP BY divisi\nHAVING AVG(gaji) > 10000000;","out":"divisi    | rata\n----------+---------\nPusat     | 30000000\nPenjualan | 10125000","lang":"sql"},{"q":"Tampilkan pelanggan_id yang punya lebih dari satu pesanan selesai.","h":"WHERE menyaring baris dulu, HAVING menyaring kelompok.","a":"SELECT pelanggan_id, COUNT(*) AS n\nFROM pesanan\nWHERE status = 'selesai'\nGROUP BY pelanggan_id\nHAVING COUNT(*) > 1;","out":"pelanggan_id | n\n-------------+--\n2            | 2","lang":"sql"}],"pro":[{"t":"Menyaring hasil kelompok dengan HAVING","tag":"Lebih singkat","why":"Menyaring hasil <code>GROUP BY</code> tidak perlu subquery. <code>HAVING</code> bekerja setelah pengelompokan, sedangkan <code>WHERE</code> sebelum pengelompokan.","lang":"sql","a":"SELECT * FROM (\n  SELECT kategori, COUNT(*) AS jumlah\n  FROM produk\n  GROUP BY kategori\n) AS r\nWHERE jumlah >= 3\nORDER BY kategori;","b":"SELECT kategori, COUNT(*) AS jumlah\nFROM produk\nGROUP BY kategori\nHAVING COUNT(*) >= 3\nORDER BY kategori;","out":"kategori | jumlah\n---------+-------\nCamilan  | 3\nMinuman  | 3"}]},{"b":["Tim gudang butuh ringkasan untuk rapat mingguan. Gunakan fungsi agregat, GROUP BY, dan HAVING."],"ex":[["Lihat produk","SELECT * FROM produk;"]],"tasks":[{"q":"Hitung jumlah produk (kolom jumlah_produk) dan total stok (kolom total_stok) per kategori.","a":"SELECT kategori, COUNT(*) AS jumlah_produk, SUM(stok) AS total_stok FROM produk GROUP BY kategori;"},{"q":"Tampilkan nilai persediaan per kategori (harga × stok, kolom nilai), urut dari terbesar.","a":"SELECT kategori, SUM(harga * stok) AS nilai FROM produk GROUP BY kategori ORDER BY nilai DESC;","order":true},{"q":"Tampilkan kategori yang rata-rata harganya di atas 50000 beserta rata-ratanya (kolom rata).","a":"SELECT kategori, AVG(harga) AS rata FROM produk GROUP BY kategori HAVING AVG(harga) > 50000;"},{"q":"Hitung jumlah pesanan per status (kolom n).","a":"SELECT status, COUNT(*) AS n FROM pesanan GROUP BY status;"}],"pts":[],"q":[]},{"b":["<code>CREATE TABLE</code> membuat tabel baru: nama tabel, lalu daftar kolom beserta tipe data dan aturannya. Perintah yang mengatur struktur seperti ini disebut <b>DDL</b> (Data Definition Language).","Rancang tabel dengan hati-hati: beri setiap tabel primary key, pilih tipe data yang tepat, dan tambahkan aturan (constraint) untuk menjaga data tetap benar sejak awal. Memperbaiki data yang terlanjur kotor jauh lebih mahal.","<code>CREATE TABLE IF NOT EXISTS</code> tidak error jika tabel sudah ada. <code>CREATE TABLE baru AS SELECT ...</code> membuat tabel dari hasil query, berguna untuk salinan atau laporan."],"ex":[["Buat tabel kategori","CREATE TABLE kategori (\n  id INTEGER PRIMARY KEY,\n  nama TEXT NOT NULL UNIQUE,\n  aktif INTEGER DEFAULT 1\n);\nINSERT INTO kategori (nama) VALUES ('Minuman'), ('Camilan');\nSELECT * FROM kategori;"],["Tabel dari hasil query","CREATE TABLE produk_mahal AS\nSELECT nama, harga FROM produk WHERE harga > 70000;\nSELECT * FROM produk_mahal;"]],"task":{"q":"Buat tabel ulasan dengan kolom id (INTEGER PRIMARY KEY), produk_id (INTEGER), bintang (INTEGER), dan komentar (TEXT). Lalu tambahkan satu ulasan: produk 1, bintang 5, komentar Mantap.","a":"CREATE TABLE ulasan (id INTEGER PRIMARY KEY, produk_id INTEGER, bintang INTEGER, komentar TEXT); INSERT INTO ulasan (produk_id, bintang, komentar) VALUES (1, 5, 'Mantap');","check":"SELECT produk_id, bintang, komentar FROM ulasan;"},"pts":["CREATE TABLE nama (kolom tipe aturan, ...).","Setiap tabel butuh primary key.","IF NOT EXISTS mencegah error tabel ganda.","CREATE TABLE ... AS SELECT menyalin hasil query."],"q":[["DDL adalah singkatan dari?",["Data Definition Language","Data Deletion Logic","Direct Data Link"],0,"DDL mengatur struktur."],["Aturan yang membuat kolom wajib diisi?",["UNIQUE","NOT NULL","DEFAULT"],1,"NOT NULL menolak nilai kosong."]],"so":[{"q":"Buat tabel kategori (id INTEGER PRIMARY KEY, nama TEXT NOT NULL), isi tiga baris, lalu tampilkan.","h":"CREATE TABLE lalu INSERT dan SELECT.","a":"CREATE TABLE kategori (\n  id INTEGER PRIMARY KEY,\n  nama TEXT NOT NULL\n);\nINSERT INTO kategori VALUES (1, 'Minuman'), (2, 'Camilan'), (3, 'Bumbu');\nSELECT * FROM kategori;","out":"id | nama\n---+--------\n1  | Minuman\n2  | Camilan\n3  | Bumbu","lang":"sql"},{"q":"Buat tabel pengiriman dengan kolom status yang bawaannya \"diproses\", lalu tambah satu baris tanpa status.","h":"DEFAULT pada definisi kolom.","a":"CREATE TABLE pengiriman (\n  id INTEGER PRIMARY KEY,\n  pesanan_id INTEGER,\n  kurir TEXT,\n  status TEXT DEFAULT 'diproses'\n);\nINSERT INTO pengiriman (id, pesanan_id, kurir) VALUES (1, 107, 'JNE');\nSELECT * FROM pengiriman;","out":"id | pesanan_id | kurir | status\n---+------------+-------+---------\n1  | 107        | JNE   | diproses","lang":"sql"}]},{"b":["<code>ALTER TABLE</code> mengubah struktur tabel yang sudah ada: menambah kolom (<code>ADD COLUMN</code>), menghapus kolom (<code>DROP COLUMN</code>), mengganti nama kolom atau tabel (<code>RENAME</code>), dan mengubah tipe kolom.","<code>DROP TABLE</code> menghapus tabel beserta seluruh isinya dan strukturnya. <code>TRUNCATE TABLE</code> mengosongkan semua baris tetapi strukturnya tetap, biasanya jauh lebih cepat daripada DELETE tanpa WHERE dan mereset penghitung id. (SQLite asli tidak punya TRUNCATE; simulator ini menyediakannya agar kamu bisa mencoba.)","Perintah-perintah ini sulit dibatalkan. Di perusahaan, perubahan struktur dilakukan lewat file <b>migrasi</b> yang ditinjau tim, bukan diketik langsung di database produksi."],"ex":[["Tambah kolom","ALTER TABLE produk ADD COLUMN berat_gram INTEGER DEFAULT 250;\nSELECT nama, berat_gram FROM produk LIMIT 3;"],["Ganti nama kolom","ALTER TABLE pelanggan RENAME COLUMN kota TO domisili;\nSELECT nama, domisili FROM pelanggan LIMIT 3;"],["TRUNCATE: kosongkan isi","TRUNCATE TABLE detail_pesanan;\nSELECT COUNT(*) AS sisa FROM detail_pesanan;"],["DROP ditolak karena masih dirujuk","DROP TABLE pelanggan;"]],"task":{"q":"Tambahkan kolom email bertipe TEXT ke tabel pelanggan.","a":"ALTER TABLE pelanggan ADD COLUMN email TEXT;","check":"SELECT * FROM pelanggan;"},"pts":["ALTER: ADD/DROP/RENAME COLUMN, RENAME TO.","DROP = struktur dan isi hilang.","TRUNCATE = isi hilang, struktur tetap.","Perubahan struktur lewat migrasi yang ditinjau."],"q":[["Perintah yang menghapus semua baris tapi tabelnya tetap ada?",["DROP TABLE","TRUNCATE TABLE","ALTER TABLE"],1,"TRUNCATE mengosongkan isi."],["Menambah kolom baru memakai?",["ALTER TABLE ... ADD COLUMN","UPDATE ... ADD","INSERT COLUMN"],0,"ALTER mengubah struktur."]],"so":[{"q":"Tambahkan kolom berat (INTEGER) ke tabel produk, isi berat Kopi Gayo 250, lalu tampilkan nama dan berat dua produk pertama.","h":"ALTER TABLE ... ADD COLUMN.","a":"ALTER TABLE produk ADD COLUMN berat INTEGER;\nUPDATE produk SET berat = 250 WHERE id = 1;\nSELECT nama, berat FROM produk WHERE id <= 2;","out":"nama       | berat\n-----------+------\nKopi Gayo  | 250\nTeh Melati | NULL","lang":"sql"},{"q":"Apa beda DELETE, TRUNCATE, dan DROP?","h":"Hapus baris, kosongkan tabel, hapus tabel.","a":"DELETE  : menghapus baris tertentu (bisa pakai WHERE), tercatat per baris.\nTRUNCATE: mengosongkan seluruh isi tabel dengan cepat, struktur tetap.\nDROP    : menghapus tabel beserta struktur dan isinya.","lang":"text"}]},{"viz":"er","b":["<b>Primary key</b> (PK) adalah kolom (atau gabungan kolom) yang nilainya unik dan tidak boleh NULL. Ia menjadi identitas setiap baris, seperti NIK untuk penduduk. Tabel detail_pesanan memakai PK gabungan (pesanan_id, produk_id), karena satu produk hanya muncul sekali dalam satu pesanan.","<b>Foreign key</b> (FK) adalah kolom yang menunjuk primary key tabel lain. <code>pesanan.pelanggan_id</code> menunjuk <code>pelanggan.id</code>. Database menjaga <b>integritas referensial</b>: kamu tidak bisa membuat pesanan untuk pelanggan yang tidak ada, dan tidak bisa menghapus pelanggan yang masih punya pesanan.","Perilaku saat induk dihapus bisa diatur: <code>ON DELETE CASCADE</code> ikut menghapus anak, <code>ON DELETE SET NULL</code> mengosongkan rujukannya. Diagram di bawah menunjukkan relasi di database Toko Nusantara."],"ex":[["Pesanan untuk pelanggan yang tidak ada","INSERT INTO pesanan (pelanggan_id, tanggal) VALUES (99, '2024-12-01');"],["Primary key kembar","INSERT INTO produk (id, nama, kategori, harga) VALUES (1, 'Kopi Lain', 'Minuman', 50000);"],["Foreign key dengan CASCADE","CREATE TABLE alamat (\n  id INTEGER PRIMARY KEY,\n  pelanggan_id INTEGER REFERENCES pelanggan(id) ON DELETE CASCADE,\n  jalan TEXT\n);\nINSERT INTO pelanggan (id, nama) VALUES (50, 'Uji');\nINSERT INTO alamat (pelanggan_id, jalan) VALUES (50, 'Jl. Merdeka 1');\nDELETE FROM pelanggan WHERE id = 50;\nSELECT COUNT(*) AS alamat_tersisa FROM alamat;"]],"task":{"q":"Buat tabel favorit dengan kolom pelanggan_id yang merujuk pelanggan(id) dan produk_id yang merujuk produk(id), dengan primary key gabungan keduanya. Lalu catat bahwa pelanggan 2 menyukai produk 6.","a":"CREATE TABLE favorit (pelanggan_id INTEGER REFERENCES pelanggan(id), produk_id INTEGER REFERENCES produk(id), PRIMARY KEY (pelanggan_id, produk_id)); INSERT INTO favorit VALUES (2, 6);","check":"SELECT pelanggan_id, produk_id FROM favorit;"},"pts":["PK: unik + tidak NULL, identitas baris.","FK: menunjuk PK tabel lain.","Integritas referensial dijaga database.","ON DELETE CASCADE / SET NULL mengatur efek penghapusan induk."],"q":[["Kolom pesanan.pelanggan_id adalah?",["Primary key","Foreign key","Index"],1,"Ia menunjuk pelanggan.id."],["Menghapus pelanggan yang masih punya pesanan (tanpa CASCADE)?",["Berhasil","Ditolak","Pesanannya ikut hilang"],1,"FK mencegah rujukan yatim."]],"so":[{"q":"Coba tambahkan detail pesanan untuk pesanan 999 yang tidak ada. Apa yang terjadi?","h":"Foreign key menolak nilai yang tidak ada di tabel induk.","a":"INSERT INTO detail_pesanan VALUES (999, 1, 1);","out":"Galat: FOREIGN KEY gagal: detail_pesanan.pesanan_id = 999 tidak ada di pesanan.id.","lang":"sql"},{"q":"Kenapa detail_pesanan memakai primary key gabungan (pesanan_id, produk_id)?","h":"Satu produk hanya boleh muncul sekali per pesanan.","a":"Kombinasi pesanan dan produk harus unik: satu produk muncul sekali di satu pesanan\n(jumlahnya disimpan di kolom jumlah). Kunci gabungan mencegah baris ganda.","lang":"text"}]},{"b":["<b>Constraint</b> adalah aturan yang dijaga oleh database itu sendiri, sehingga data salah ditolak dari mana pun asalnya: aplikasi web, aplikasi mobile, atau admin yang mengetik query.","<code>NOT NULL</code> mewajibkan kolom diisi. <code>UNIQUE</code> melarang nilai kembar, misalnya email. <code>CHECK (kondisi)</code> memastikan nilai memenuhi syarat, misalnya <code>harga &gt; 0</code> atau <code>bintang BETWEEN 1 AND 5</code>. <code>DEFAULT</code> memberi nilai bawaan.","Coba jalankan contoh di bawah dan baca pesan error-nya. Pesan seperti ini adalah teman: ia menghentikan data rusak sebelum masuk."],"ex":[["Harga negatif ditolak CHECK","INSERT INTO produk (nama, kategori, harga) VALUES ('Promo', 'Camilan', -1000);"],["Saldo tidak boleh minus","UPDATE rekening SET saldo = saldo - 1000000 WHERE id = 1;"],["UNIQUE menolak duplikat","CREATE TABLE akun (\n  id INTEGER PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE,\n  umur INTEGER CHECK (umur >= 13)\n);\nINSERT INTO akun (email, umur) VALUES ('rina@mail.com', 20);\nINSERT INTO akun (email, umur) VALUES ('rina@mail.com', 25);"],["NOT NULL menolak kosong","INSERT INTO pesanan (pelanggan_id) VALUES (1);"]],"task":{"q":"Buat tabel voucher dengan kolom kode (TEXT, NOT NULL, UNIQUE) dan potongan (INTEGER) yang harus antara 1 dan 100 (pakai CHECK). Tambahkan voucher HEMAT10 dengan potongan 10.","a":"CREATE TABLE voucher (kode TEXT NOT NULL UNIQUE, potongan INTEGER CHECK (potongan BETWEEN 1 AND 100)); INSERT INTO voucher VALUES ('HEMAT10', 10);","check":"SELECT kode, potongan FROM voucher;"},"pts":["Constraint dijaga database, bukan hanya aplikasi.","NOT NULL, UNIQUE, CHECK, DEFAULT, PK, FK.","Pesan error constraint membantu menemukan data salah.","Tambahkan constraint sejak awal desain tabel."],"q":[["Aturan agar email tidak kembar?",["NOT NULL","UNIQUE","CHECK"],1,"UNIQUE melarang duplikat."],["<code>CHECK (stok &gt;= 0)</code> mencegah?",["Stok kosong","Stok negatif","Stok di atas 100"],1,"CHECK menguji kondisi."]],"so":[{"q":"Coba ubah harga Teh Melati menjadi -5. Constraint apa yang menolaknya?","h":"Lihat definisi kolom harga di tabel produk.","a":"UPDATE produk SET harga = -5 WHERE id = 2;","out":"Galat: Nilai melanggar aturan CHECK pada kolom produk.harga.","lang":"sql"},{"q":"Buat tabel member dengan email UNIQUE, lalu coba masukkan email yang sama dua kali.","h":"Baris kedua harus ditolak.","a":"CREATE TABLE member (\n  id INTEGER PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE\n);\nINSERT INTO member VALUES (1, 'rina@mail.id');\nINSERT INTO member VALUES (2, 'rina@mail.id');","out":"Galat: Nilai rina@mail.id sudah ada di member.email (UNIQUE).","lang":"sql"}]},{"viz":"join","vj":"INNER","b":["Data yang saling berhubungan tersimpan di tabel terpisah. <b>JOIN</b> menyatukannya kembali dalam satu hasil. <code>INNER JOIN</code> (atau cukup <code>JOIN</code>) hanya mengambil pasangan baris yang cocok dengan kondisi <code>ON</code> di kedua tabel.","Kondisi ON biasanya mencocokkan foreign key dengan primary key: <code>ON pesanan.pelanggan_id = pelanggan.id</code>. Pakai alias tabel agar query ringkas, dan tulis nama tabel di depan kolom yang namanya sama di kedua tabel, seperti <code>id</code>.","Perhatikan visualisasi: setiap baris kiri dicocokkan dengan setiap baris kanan. Garis muncul untuk pasangan yang cocok, dan hanya pasangan itulah yang masuk hasil. Pelanggan tanpa pesanan tidak muncul sama sekali."],"ex":[["Pesanan beserta nama pelanggannya","SELECT s.id, s.tanggal, p.nama\nFROM pesanan s\nJOIN pelanggan p ON s.pelanggan_id = p.id;"],["JOIN + WHERE + ORDER","SELECT p.nama, s.id, s.status\nFROM pelanggan p\nINNER JOIN pesanan s ON s.pelanggan_id = p.id\nWHERE p.kota = 'Jakarta'\nORDER BY s.id;"],["Kolom ambigu tanpa nama tabel","SELECT id, nama FROM pelanggan JOIN pesanan ON pesanan.pelanggan_id = pelanggan.id;"]],"task":{"q":"Tampilkan nama produk dan jumlah untuk setiap baris di detail_pesanan dengan pesanan_id 104.","a":"SELECT pr.nama, d.jumlah FROM detail_pesanan d JOIN produk pr ON pr.id = d.produk_id WHERE d.pesanan_id = 104;"},"pts":["INNER JOIN hanya mengambil pasangan yang cocok.","ON berisi kondisi pencocokan, biasanya FK = PK.","Pakai alias tabel.","Kolom bernama sama harus diberi awalan tabel."],"q":[["Pelanggan tanpa pesanan pada INNER JOIN pelanggan-pesanan?",["Muncul dengan NULL","Tidak muncul","Muncul dua kali"],1,"INNER hanya mengambil yang cocok."],["Error \"kolom ambigu\" berarti?",["Kolom tidak ada","Kolom ada di lebih dari satu tabel","Tabel kosong"],1,"Tulis tabel.kolom."]],"so":[{"q":"Tampilkan id pesanan, tanggal, dan nama pelanggan untuk pesanan berstatus selesai.","h":"JOIN pelanggan ON pelanggan.id = pesanan.pelanggan_id.","a":"SELECT s.id, s.tanggal, p.nama\nFROM pesanan s\nJOIN pelanggan p ON p.id = s.pelanggan_id\nWHERE s.status = 'selesai'\nORDER BY s.id;","out":"id  | tanggal    | nama\n----+------------+------\n101 | 2024-10-01 | Andi\n102 | 2024-10-03 | Budi\n104 | 2024-10-12 | Citra\n106 | 2024-10-20 | Budi\n109 | 2024-11-09 | Eko","lang":"sql"},{"q":"Tampilkan nama produk dan total unit terjual per produk, urut dari terbanyak.","h":"JOIN detail_pesanan dengan produk, lalu GROUP BY.","a":"SELECT pr.nama, SUM(d.jumlah) AS terjual\nFROM detail_pesanan d\nJOIN produk pr ON pr.id = d.produk_id\nGROUP BY pr.nama\nORDER BY terjual DESC;","out":"nama             | terjual\n-----------------+--------\nKerupuk Udang    | 14\nKeripik Singkong | 10\nSambal Bawang    | 7\nTeh Melati       | 5\nKopi Gayo        | 4\nMadu Hutan       | 2\nKacang Mete      | 2\nRendang Kaleng   | 2","lang":"sql"}]},{"viz":"join","vj":"LEFT","b":["<b>Outer join</b> tetap mempertahankan baris yang tidak punya pasangan. <code>LEFT JOIN</code> mempertahankan semua baris tabel kiri; jika tidak ada pasangan di kanan, kolom kanan diisi NULL. <code>RIGHT JOIN</code> kebalikannya. <code>FULL OUTER JOIN</code> mempertahankan semua baris dari kedua sisi.","Pola yang sangat sering dipakai: \"cari yang <i>tidak</i> punya pasangan\". LEFT JOIN lalu saring <code>WHERE kanan.id IS NULL</code>, misalnya pelanggan yang belum pernah memesan.","Gunakan tombol jenis JOIN di visualisasi untuk membandingkan hasilnya. Perhatikan baris yang diberi NULL. (MySQL tidak punya FULL OUTER JOIN; gantinya LEFT JOIN UNION RIGHT JOIN.)"],"ex":[["Semua pelanggan, punya pesanan atau tidak","SELECT p.nama, s.id AS pesanan\nFROM pelanggan p\nLEFT JOIN pesanan s ON s.pelanggan_id = p.id\nORDER BY p.id;"],["Pelanggan yang belum pernah memesan","SELECT p.nama\nFROM pelanggan p\nLEFT JOIN pesanan s ON s.pelanggan_id = p.id\nWHERE s.id IS NULL;"],["RIGHT JOIN","SELECT p.nama, s.id\nFROM pesanan s\nRIGHT JOIN pelanggan p ON s.pelanggan_id = p.id;"],["FULL OUTER JOIN","SELECT pr.nama, d.pesanan_id\nFROM produk pr\nFULL OUTER JOIN detail_pesanan d ON d.produk_id = pr.id\nWHERE d.pesanan_id IS NULL OR pr.id IS NULL;"]],"task":{"q":"Tampilkan nama semua produk dan total jumlah terjualnya (alias terjual). Produk yang belum pernah terjual tetap muncul dengan terjual NULL.","a":"SELECT pr.nama, SUM(d.jumlah) AS terjual FROM produk pr LEFT JOIN detail_pesanan d ON d.produk_id = pr.id GROUP BY pr.id, pr.nama;"},"pts":["LEFT: semua baris kiri; RIGHT: semua baris kanan; FULL: semua dari keduanya.","Baris tanpa pasangan diisi NULL.","Pola anti-join: LEFT JOIN ... WHERE kanan.id IS NULL.","Urutan tabel menentukan mana \"kiri\"."],"q":[["Mencari produk yang belum pernah dipesan?",["INNER JOIN","LEFT JOIN + WHERE d.produk_id IS NULL","CROSS JOIN"],1,"Baris kiri tanpa pasangan."],["<code>A RIGHT JOIN B</code> setara dengan?",["B LEFT JOIN A","A LEFT JOIN B","A INNER JOIN B"],0,"Tinggal tukar posisi tabel."]],"so":[{"q":"Tampilkan semua pelanggan beserta jumlah pesanannya, termasuk yang belum pernah memesan (0).","h":"LEFT JOIN lalu COUNT(kolom tabel kanan).","a":"SELECT p.nama, COUNT(s.id) AS n_pesanan\nFROM pelanggan p\nLEFT JOIN pesanan s ON s.pelanggan_id = p.id\nGROUP BY p.nama\nORDER BY n_pesanan DESC, p.nama;","out":"nama  | n_pesanan\n------+----------\nAndi  | 3\nBudi  | 2\nCitra | 1\nDewi  | 1\nEko   | 1\nFitri | 1\nHadi  | 1\nGita  | 0","lang":"sql"},{"q":"Tampilkan produk yang tidak terjual sama sekali di bulan November 2024.","h":"LEFT JOIN ke subquery penjualan November, lalu WHERE kolom kanan IS NULL.","a":"SELECT pr.nama\nFROM produk pr\nLEFT JOIN (\n  SELECT d.produk_id\n  FROM detail_pesanan d\n  JOIN pesanan s ON s.id = d.pesanan_id\n  WHERE s.tanggal >= '2024-11-01'\n) nov ON nov.produk_id = pr.id\nWHERE nov.produk_id IS NULL;","out":"nama\n--------------\nTeh Melati\nKacang Mete\nRendang Kaleng","lang":"sql"}]},{"viz":"join","vj":"SELF","b":["<b>Self join</b> menggabungkan tabel dengan dirinya sendiri. Contoh klasiknya hierarki karyawan: kolom <code>atasan_id</code> menunjuk <code>id</code> di tabel yang sama. Kuncinya adalah memberi dua alias berbeda, misalnya <code>k</code> untuk karyawan dan <code>a</code> untuk atasan.","<b>Cross join</b> memasangkan setiap baris kiri dengan <i>setiap</i> baris kanan tanpa syarat. Hasilnya disebut produk kartesius: 8 pelanggan × 8 produk = 64 baris. Berguna untuk membuat kombinasi, misalnya semua ukuran × semua warna.","Hati-hati: lupa menulis kondisi ON pada join gaya lama (<code>FROM a, b</code>) diam-diam menghasilkan cross join yang sangat besar."],"ex":[["Karyawan dan atasannya","SELECT k.nama AS karyawan, k.jabatan, a.nama AS atasan\nFROM karyawan k\nLEFT JOIN karyawan a ON k.atasan_id = a.id;"],["Rekan satu atasan","SELECT x.nama, y.nama AS rekan\nFROM karyawan x JOIN karyawan y\n  ON x.atasan_id = y.atasan_id AND x.id < y.id;"],["Cross join: kombinasi","SELECT u.ukuran, w.warna\nFROM (SELECT 'S' AS ukuran UNION ALL SELECT 'M' UNION ALL SELECT 'L') u\nCROSS JOIN (SELECT 'Merah' AS warna UNION ALL SELECT 'Hitam') w;"],["Jumlah baris produk kartesius","SELECT COUNT(*) AS kombinasi FROM pelanggan CROSS JOIN produk;"]],"task":{"q":"Tampilkan nama setiap karyawan dan nama atasannya (kolom karyawan dan atasan) hanya untuk karyawan yang punya atasan.","a":"SELECT k.nama AS karyawan, a.nama AS atasan FROM karyawan k JOIN karyawan a ON k.atasan_id = a.id;"},"pts":["Self join butuh dua alias.","Cross join = semua kombinasi (kartesius).","Jumlah baris cross join = baris kiri × baris kanan.","Selalu tulis kondisi ON."],"q":[["Cross join 3 baris dengan 4 baris menghasilkan?",["7 baris","12 baris","4 baris"],1,"3 × 4 = 12."],["Kenapa self join butuh alias?",["Wajib di semua query","Agar dua \"salinan\" tabel bisa dibedakan","Lebih cepat"],1,"Satu tabel berperan dua kali."]],"so":[{"q":"Tampilkan pasangan karyawan yang satu divisi (tanpa memasangkan dengan diri sendiri dan tanpa pasangan ganda).","h":"Self join dengan a.id &lt; b.id.","a":"SELECT a.nama AS karyawan1, b.nama AS karyawan2, a.divisi\nFROM karyawan a\nJOIN karyawan b ON a.divisi = b.divisi AND a.id < b.id\nORDER BY a.divisi, a.nama;","out":"karyawan1 | karyawan2 | divisi\n----------+-----------+----------\nTono      | Vino      | Gudang\nTono      | Wati      | Gudang\nVino      | Wati      | Gudang\nUmi       | Yudi      | Penjualan\nUmi       | Zahra     | Penjualan\nUmi       | Rio       | Penjualan\nYudi      | Zahra     | Penjualan\nYudi      | Rio       | Penjualan\nZahra     | Rio       | Penjualan","lang":"sql"},{"q":"Buat semua kombinasi ukuran (S, L) dengan produk Minuman memakai CROSS JOIN.","h":"Buat tabel ukuran kecil dengan SELECT ... UNION ALL.","a":"WITH ukuran(u) AS (SELECT 'S' UNION ALL SELECT 'L')\nSELECT pr.nama, ukuran.u\nFROM produk pr\nCROSS JOIN ukuran\nWHERE pr.kategori = 'Minuman'\nORDER BY pr.nama, ukuran.u;","out":"nama       | u\n-----------+--\nKopi Gayo  | L\nKopi Gayo  | S\nMadu Hutan | L\nMadu Hutan | S\nTeh Melati | L\nTeh Melati | S","lang":"sql"}]},{"b":["Pertanyaan bisnis sering membutuhkan beberapa tabel sekaligus. \"Berapa total belanja tiap pelanggan?\" melibatkan pelanggan → pesanan → detail_pesanan → produk. Tulis JOIN satu per satu mengikuti jalur relasi.","Bacalah query seperti rantai: setiap JOIN menambah satu tabel dan satu kondisi ON yang menghubungkannya dengan tabel sebelumnya. Setelah semua tergabung, gunakan WHERE, GROUP BY, dan ORDER BY seperti biasa.","Kesalahan umum adalah lupa satu kondisi ON sehingga baris berlipat ganda. Jika jumlah hasil tiba-tiba terlalu besar, periksa kembali setiap kondisi ON."],"ex":[["Total belanja per pelanggan (tanpa yang batal)","SELECT p.nama, SUM(d.jumlah * pr.harga) AS total\nFROM pelanggan p\nJOIN pesanan s ON s.pelanggan_id = p.id\nJOIN detail_pesanan d ON d.pesanan_id = s.id\nJOIN produk pr ON pr.id = d.produk_id\nWHERE s.status <> 'batal'\nGROUP BY p.id, p.nama\nORDER BY total DESC;"],["Isi pesanan lengkap","SELECT s.id, p.nama AS pembeli, pr.nama AS produk, d.jumlah\nFROM pesanan s\nJOIN pelanggan p ON p.id = s.pelanggan_id\nJOIN detail_pesanan d ON d.pesanan_id = s.id\nJOIN produk pr ON pr.id = d.produk_id\nWHERE s.id IN (101, 104)\nORDER BY s.id, pr.nama;"]],"task":{"q":"Tampilkan kategori produk dan total pendapatan per kategori (alias pendapatan = jumlah * harga) dari semua pesanan berstatus selesai.","a":"SELECT pr.kategori, SUM(d.jumlah * pr.harga) AS pendapatan FROM detail_pesanan d JOIN pesanan s ON s.id = d.pesanan_id JOIN produk pr ON pr.id = d.produk_id WHERE s.status = 'selesai' GROUP BY pr.kategori;"},"pts":["Ikuti jalur relasi tabel demi tabel.","Satu JOIN = satu kondisi ON.","Hasil terlalu besar? Periksa kondisi ON.","Agregasi dilakukan setelah semua tabel tergabung."],"q":[["Berapa JOIN untuk menggabungkan 4 tabel?",["2","3","4"],1,"Setiap JOIN menambah satu tabel."],["Gejala lupa kondisi ON?",["Hasil kosong","Baris berlipat ganda","Error sintaks selalu"],1,"Tanpa syarat, terjadi kombinasi kartesius."]],"so":[{"q":"Tampilkan nama pelanggan, nama produk, dan jumlah untuk semua pesanan berstatus selesai.","h":"Gabungkan empat tabel: pesanan, pelanggan, detail_pesanan, produk.","a":"SELECT p.nama AS pelanggan, pr.nama AS produk, d.jumlah\nFROM pesanan s\nJOIN pelanggan p ON p.id = s.pelanggan_id\nJOIN detail_pesanan d ON d.pesanan_id = s.id\nJOIN produk pr ON pr.id = d.produk_id\nWHERE s.status = 'selesai'\nORDER BY p.nama, pr.nama;","out":"pelanggan | produk           | jumlah\n----------+------------------+-------\nAndi      | Keripik Singkong | 5\nAndi      | Kopi Gayo        | 2\nBudi      | Kerupuk Udang    | 4\nBudi      | Rendang Kaleng   | 2\nBudi      | Teh Melati       | 3\nBudi      | Teh Melati       | 2\nCitra     | Kacang Mete      | 2\nCitra     | Keripik Singkong | 3\nCitra     | Sambal Bawang    | 1\nEko       | Sambal Bawang    | 6","lang":"sql"},{"q":"Hitung total belanja (jumlah x harga) per kota pelanggan, urut dari terbesar.","h":"JOIN empat tabel lalu GROUP BY kota.","a":"SELECT p.kota, SUM(d.jumlah * pr.harga) AS total\nFROM pesanan s\nJOIN pelanggan p ON p.id = s.pelanggan_id\nJOIN detail_pesanan d ON d.pesanan_id = s.id\nJOIN produk pr ON pr.id = d.produk_id\nGROUP BY p.kota\nORDER BY total DESC;","out":"kota       | total\n-----------+-------\nJakarta    | 655000\nBandung    | 555000\nSurabaya   | 195000\nMedan      | 180000\nYogyakarta | 30000","lang":"sql"}]},{"b":["Tim layanan pelanggan ingin melihat siapa membeli apa. Gabungkan pelanggan, pesanan, detail_pesanan, dan produk."],"ex":[["Lihat pesanan","SELECT * FROM pesanan;"]],"tasks":[{"q":"Tampilkan id pesanan, nama pelanggan, dan status untuk semua pesanan.","a":"SELECT s.id, p.nama, s.status FROM pesanan s JOIN pelanggan p ON p.id = s.pelanggan_id;"},{"q":"Tampilkan nama pelanggan yang belum pernah memesan.","a":"SELECT p.nama FROM pelanggan p LEFT JOIN pesanan s ON s.pelanggan_id = p.id WHERE s.id IS NULL;"},{"q":"Hitung total belanja (jumlah × harga, kolom total) setiap pesanan berstatus selesai, tampilkan id pesanan dan total.","a":"SELECT s.id, SUM(d.jumlah * pr.harga) AS total FROM pesanan s JOIN detail_pesanan d ON d.pesanan_id = s.id JOIN produk pr ON pr.id = d.produk_id WHERE s.status = 'selesai' GROUP BY s.id;"},{"q":"Tampilkan nama karyawan dan nama atasannya (kolom atasan); karyawan tanpa atasan tetap tampil.","a":"SELECT k.nama, a.nama AS atasan FROM karyawan k LEFT JOIN karyawan a ON a.id = k.atasan_id;"}],"pts":[],"q":[]},{"b":["<b>Subquery</b> adalah SELECT di dalam kurung yang dipakai oleh query lain. Bentuknya menentukan di mana ia boleh dipakai. <b>Skalar</b> mengembalikan satu nilai, bisa dipakai di mana pun nilai tunggal diperlukan, misalnya <code>WHERE harga &gt; (SELECT AVG(harga) FROM produk)</code>.","Subquery <b>kolom</b> mengembalikan satu kolom banyak baris, dipakai bersama <code>IN</code>, <code>ANY</code>, atau <code>ALL</code>. Subquery <b>tabel</b> mengembalikan banyak kolom dan baris, dipakai di FROM sebagai tabel sementara (wajib diberi alias).","Subquery bisa <b>bersarang</b> beberapa tingkat. Database menjalankan yang paling dalam lebih dulu. Jika sudah lebih dari dua tingkat, pertimbangkan CTE (WITH) agar lebih mudah dibaca."],"ex":[["Skalar: di atas rata-rata","SELECT nama, harga FROM produk\nWHERE harga > (SELECT AVG(harga) FROM produk);"],["Kolom: pelanggan yang pernah memesan","SELECT nama FROM pelanggan\nWHERE id IN (SELECT pelanggan_id FROM pesanan);"],["Tabel: di FROM","SELECT kategori, rata FROM (\n  SELECT kategori, AVG(harga) AS rata FROM produk GROUP BY kategori\n) AS t\nWHERE rata > 40000;"],["Bersarang: pembeli Kopi Gayo","SELECT nama FROM pelanggan WHERE id IN (\n  SELECT pelanggan_id FROM pesanan WHERE id IN (\n    SELECT pesanan_id FROM detail_pesanan WHERE produk_id = (\n      SELECT id FROM produk WHERE nama = 'Kopi Gayo')));"]],"task":{"q":"Tampilkan nama dan harga produk termahal memakai subquery skalar MAX.","a":"SELECT nama, harga FROM produk WHERE harga = (SELECT MAX(harga) FROM produk);"},"pts":["Skalar = satu nilai; kolom = satu kolom; tabel = banyak kolom.","Subquery di FROM wajib alias.","IN untuk subquery kolom.","Bersarang dijalankan dari dalam ke luar."],"q":[["Subquery di <code>WHERE harga &gt; (...)</code> harus mengembalikan?",["Satu nilai","Satu tabel","Satu kolom banyak baris"],0,"Perbandingan > butuh nilai tunggal."],["Operator untuk subquery yang mengembalikan banyak baris?",["=","IN","LIKE"],1,"IN memeriksa keanggotaan."]],"so":[{"q":"Tampilkan karyawan yang gajinya di atas rata-rata seluruh karyawan.","h":"Subquery skalar di WHERE: (SELECT AVG(gaji) FROM karyawan).","a":"SELECT nama, gaji\nFROM karyawan\nWHERE gaji > (SELECT AVG(gaji) FROM karyawan)\nORDER BY gaji DESC;","out":"nama | gaji\n-----+---------\nSari | 30000000\nUmi  | 16000000\nTono | 15000000","lang":"sql"},{"q":"Tampilkan nama produk beserta selisih harganya dari harga termurah.","h":"Subquery skalar di SELECT.","a":"SELECT nama, harga - (SELECT MIN(harga) FROM produk) AS selisih\nFROM produk\nORDER BY selisih;","out":"nama             | selisih\n-----------------+--------\nKeripik Singkong | 0\nKerupuk Udang    | 5000\nTeh Melati       | 10000\nSambal Bawang    | 15000\nKacang Mete      | 45000\nRendang Kaleng   | 60000\nKopi Gayo        | 70000\nMadu Hutan       | 105000","lang":"sql"}]},{"b":["<b>Correlated subquery</b> memakai kolom dari query luar, sehingga ia dihitung ulang untuk setiap baris luar. Contoh: \"karyawan yang gajinya di atas rata-rata <i>divisinya sendiri</i>\". Subquery butuh divisi dari baris karyawan yang sedang diperiksa.","<code>EXISTS (subquery)</code> bernilai benar jika subquery menghasilkan minimal satu baris. Ia biasanya ditulis sebagai correlated subquery: \"pelanggan yang punya pesanan berstatus dikirim\". <code>NOT EXISTS</code> untuk kebalikannya.","Correlated subquery mudah dibaca tetapi bisa lambat pada tabel besar karena dijalankan berulang. Sering kali query yang sama bisa ditulis ulang dengan JOIN atau window function. Database modern juga cukup pintar mengoptimalkannya."],"ex":[["Di atas rata-rata divisinya","SELECT k.nama, k.divisi, k.gaji\nFROM karyawan k\nWHERE k.gaji > (SELECT AVG(x.gaji) FROM karyawan x WHERE x.divisi = k.divisi);"],["EXISTS","SELECT nama FROM pelanggan p\nWHERE EXISTS (SELECT 1 FROM pesanan s WHERE s.pelanggan_id = p.id AND s.status = 'dikirim');"],["NOT EXISTS: belum pernah memesan","SELECT nama FROM pelanggan p\nWHERE NOT EXISTS (SELECT 1 FROM pesanan s WHERE s.pelanggan_id = p.id);"],["Subquery di SELECT","SELECT nama,\n  (SELECT COUNT(*) FROM pesanan s WHERE s.pelanggan_id = p.id) AS banyak_pesanan\nFROM pelanggan p ORDER BY banyak_pesanan DESC;"]],"task":{"q":"Tampilkan nama produk yang pernah dipesan minimal sekali, memakai EXISTS.","a":"SELECT nama FROM produk pr WHERE EXISTS (SELECT 1 FROM detail_pesanan d WHERE d.produk_id = pr.id);"},"pts":["Correlated = memakai kolom query luar.","Dihitung ulang per baris luar.","EXISTS benar jika ada minimal satu baris.","Bisa ditulis ulang dengan JOIN untuk performa."],"q":[["Ciri correlated subquery?",["Memakai kolom dari query luar","Selalu di FROM","Selalu mengembalikan satu baris"],0,"Ia bergantung pada baris luar."],["<code>SELECT 1</code> di dalam EXISTS dipakai karena?",["Wajib","Isi kolom tidak penting, hanya ada tidaknya baris","Lebih akurat"],1,"EXISTS hanya peduli ada atau tidak."]],"so":[{"q":"Tampilkan produk yang harganya paling mahal di kategorinya masing-masing.","h":"Correlated subquery: bandingkan dengan MAX(harga) dari kategori yang sama.","a":"SELECT nama, kategori, harga\nFROM produk p\nWHERE harga = (SELECT MAX(harga) FROM produk WHERE kategori = p.kategori)\nORDER BY kategori;","out":"nama           | kategori | harga\n---------------+----------+-------\nSambal Bawang  | Bumbu    | 30000\nKacang Mete    | Camilan  | 60000\nRendang Kaleng | Makanan  | 75000\nMadu Hutan     | Minuman  | 120000","lang":"sql"},{"q":"Tampilkan pelanggan yang belum pernah punya pesanan, memakai NOT EXISTS.","h":"NOT EXISTS (SELECT 1 FROM pesanan WHERE pelanggan_id = p.id).","a":"SELECT nama\nFROM pelanggan p\nWHERE NOT EXISTS (SELECT 1 FROM pesanan s WHERE s.pelanggan_id = p.id);","out":"nama\n----\nGita","lang":"sql"}],"pro":[{"t":"Cek keberadaan dengan EXISTS","tag":"Lebih cepat","why":"<code>EXISTS</code> berhenti begitu satu baris cocok ditemukan, sedangkan <code>COUNT(*) &gt; 0</code> menghitung semuanya dulu.","lang":"sql","a":"SELECT nama FROM pelanggan c\nWHERE (SELECT COUNT(*) FROM pesanan o WHERE o.pelanggan_id = c.id) > 0\nORDER BY nama\nLIMIT 5;","b":"SELECT nama FROM pelanggan c\nWHERE EXISTS (SELECT 1 FROM pesanan o WHERE o.pelanggan_id = c.id)\nORDER BY nama\nLIMIT 5;","out":"nama\n-----\nAndi\nBudi\nCitra\nDewi\nEko"}]},{"b":["Bagian pemasaran mencari produk untuk promosi. Selesaikan dengan subquery."],"ex":[["Rata-rata harga","SELECT AVG(harga) FROM produk;"]],"tasks":[{"q":"Tampilkan nama dan harga produk yang harganya di atas rata-rata semua produk.","a":"SELECT nama, harga FROM produk WHERE harga > (SELECT AVG(harga) FROM produk);"},{"q":"Tampilkan nama produk yang ada di pesanan berstatus batal (pakai subquery IN bertingkat).","a":"SELECT nama FROM produk WHERE id IN (SELECT produk_id FROM detail_pesanan WHERE pesanan_id IN (SELECT id FROM pesanan WHERE status = 'batal'));"},{"q":"Tampilkan nama pelanggan yang punya minimal satu pesanan berstatus dikirim (pakai EXISTS).","a":"SELECT nama FROM pelanggan p WHERE EXISTS (SELECT 1 FROM pesanan s WHERE s.pelanggan_id = p.id AND s.status = 'dikirim');"}],"pts":[],"q":[]},{"b":["Fungsi <b>angka</b>: <code>ABS</code> nilai mutlak, <code>ROUND(x, n)</code> membulatkan ke n desimal, <code>CEILING</code>/<code>CEIL</code> ke atas, <code>FLOOR</code> ke bawah, <code>MOD(a, b)</code> atau <code>a % b</code> sisa bagi.","Fungsi <b>teks</b>: <code>UPPER</code>/<code>LOWER</code> mengubah huruf, <code>LENGTH</code> panjang teks, <code>SUBSTRING(teks, mulai, panjang)</code> mengambil potongan (posisi mulai dari 1), <code>REPLACE</code> mengganti, dan <code>CONCAT</code> atau operator <code>||</code> untuk menyambung.","Nama fungsi sedikit berbeda antar database (misalnya <code>LEN</code> di SQL Server, <code>CHAR_LENGTH</code> di MySQL), tetapi konsepnya sama. Simulator ini menerima beberapa variasi nama yang umum."],"ex":[["Fungsi angka","SELECT ABS(-7) AS mutlak, ROUND(85000 * 1.11, -2) AS bulat_ratusan,\n       CEILING(4.1) AS atas, FLOOR(4.9) AS bawah, MOD(17, 5) AS sisa;"],["Harga per 1000 dibulatkan","SELECT nama, ROUND(harga / 1000.0, 1) AS ribu FROM produk;"],["Fungsi teks","SELECT UPPER(nama) AS besar, LOWER(kategori) AS kecil, LENGTH(nama) AS panjang,\n       SUBSTRING(nama, 1, 4) AS awal, REPLACE(nama, ' ', '_') AS slug\nFROM produk;"],["Menyambung teks","SELECT CONCAT(nama, ' (', kota, ')') AS label, nama || ' - ' || COALESCE(kota, '?') AS label2\nFROM pelanggan;"]],"task":{"q":"Tampilkan nama pelanggan dalam huruf besar (alias nama_besar) dan 3 huruf pertama kotanya (alias kode_kota), untuk pelanggan yang kotanya tidak NULL.","a":"SELECT UPPER(nama) AS nama_besar, SUBSTRING(kota, 1, 3) AS kode_kota FROM pelanggan WHERE kota IS NOT NULL;"},"pts":["ROUND, CEILING, FLOOR, ABS, MOD untuk angka.","UPPER, LOWER, LENGTH, SUBSTRING, REPLACE, CONCAT untuk teks.","SUBSTRING dimulai dari posisi 1.","CONCAT mengabaikan NULL; || dengan NULL menghasilkan NULL."],"q":[["<code>SUBSTRING('Jakarta', 2, 3)</code>?",["'Jak'","'aka'","'kar'"],1,"Mulai huruf ke-2, ambil 3 huruf."],["<code>FLOOR(7.9)</code>?",["8","7","7.9"],1,"FLOOR selalu ke bawah."]],"so":[{"q":"Buat kode SKU dari 3 huruf pertama kategori (huruf besar), tanda hubung, dan id produk.","h":"UPPER, SUBSTRING, dan ||.","a":"SELECT nama, UPPER(SUBSTRING(kategori, 1, 3)) || '-' || id AS sku FROM produk;","out":"nama             | sku\n-----------------+------\nKopi Gayo        | MIN-1\nTeh Melati       | MIN-2\nKeripik Singkong | CAM-3\nKacang Mete      | CAM-4\nSambal Bawang    | BUM-5\nMadu Hutan       | MIN-6\nRendang Kaleng   | MAK-7\nKerupuk Udang    | CAM-8","lang":"sql"},{"q":"Tampilkan nama produk yang panjangnya lebih dari 10 karakter beserta panjangnya.","h":"LENGTH(nama).","a":"SELECT nama, LENGTH(nama) AS panjang FROM produk WHERE LENGTH(nama) > 10 ORDER BY panjang DESC;","out":"nama             | panjang\n-----------------+--------\nKeripik Singkong | 16\nRendang Kaleng   | 14\nSambal Bawang    | 13\nKerupuk Udang    | 13\nKacang Mete      | 11","lang":"sql"}]},{"b":["Setiap database punya fungsi tanggal sendiri. Di SQLite (dan simulator ini) tanggal disimpan sebagai teks ISO <code>YYYY-MM-DD</code>, lalu diolah dengan <code>DATE</code>, <code>TIME</code>, <code>DATETIME</code>/<code>TIMESTAMP</code>, dan <code>STRFTIME</code>. Contoh: <code>DATE('2024-10-28', '+7 days')</code>.","SQL Server memakai <code>DATEADD(day, 7, tanggal)</code> untuk menambah dan <code>DATEPART(month, tanggal)</code> untuk mengambil bagian tanggal. PostgreSQL memakai <code>tanggal + INTERVAL '7 days'</code> dan <code>EXTRACT(MONTH FROM tanggal)</code>. Simulator ini juga menerima DATEADD, DATEPART, DATEDIFF, dan EXTRACT supaya kamu bisa mencoba gaya-gaya itu.","Tanggal ISO bisa dibandingkan dan diurutkan seperti teks biasa karena urutannya tahun, bulan, lalu hari. Itu sebabnya format ini sangat dianjurkan."],"ex":[["Gaya SQLite","SELECT DATE('2024-10-28', '+7 days') AS seminggu,\n       DATE('2024-10-28', 'start of month') AS awal_bulan,\n       STRFTIME('%d/%m/%Y', '2024-10-28') AS format_indo;"],["Gaya SQL Server: DATEADD & DATEPART","SELECT id, tanggal,\n       DATEADD(day, 3, tanggal) AS estimasi_tiba,\n       DATEPART(month, tanggal) AS bulan\nFROM pesanan;"],["Selisih hari & EXTRACT","SELECT nama, bergabung,\n       DATEDIFF(day, bergabung, '2024-12-31') AS hari_menjadi_member,\n       EXTRACT(YEAR FROM bergabung) AS tahun\nFROM pelanggan;"],["Waktu sekarang","SELECT CURRENT_DATE AS hari_ini, CURRENT_TIMESTAMP AS sekarang;"]],"task":{"q":"Tampilkan id pesanan dan tanggal jatuh tempo (alias jatuh_tempo) yaitu 14 hari setelah tanggal pesanan, untuk pesanan berstatus baru.","a":"SELECT id, DATE(tanggal, '+14 days') AS jatuh_tempo FROM pesanan WHERE status = 'baru';"},"pts":["Simpan tanggal dalam format ISO.","SQLite: DATE/STRFTIME dengan pengubah teks.","SQL Server: DATEADD, DATEPART, DATEDIFF.","PostgreSQL: INTERVAL dan EXTRACT."],"q":[["<code>DATE('2024-01-31', '+1 day')</code>?",["'2024-01-32'","'2024-02-01'","Error"],1,"Fungsi tanggal paham panjang bulan."],["Kenapa format YYYY-MM-DD bisa diurutkan seperti teks?",["Kebetulan","Urutan karakternya tahun, bulan, hari","Karena ada tanda minus"],1,"Bagian terbesar di depan."]],"so":[{"q":"Tampilkan nama pelanggan dan lama menjadi member (hari) per 31 Desember 2024.","h":"DATEDIFF(day, bergabung, '2024-12-31').","a":"SELECT nama, DATEDIFF(day, bergabung, '2024-12-31') AS hari\nFROM pelanggan\nORDER BY hari DESC;","out":"nama  | hari\n------+-----\nAndi  | 716\nBudi  | 670\nCitra | 560\nDewi  | 358\nEko   | 321\nFitri | 215\nGita  | 173\nHadi  | 119","lang":"sql"},{"q":"Hitung jumlah pesanan per bulan (format YYYY-MM).","h":"STRFTIME('%Y-%m', tanggal) lalu GROUP BY.","a":"SELECT STRFTIME('%Y-%m', tanggal) AS bulan, COUNT(*) AS n\nFROM pesanan\nGROUP BY bulan\nORDER BY bulan;","out":"bulan   | n\n--------+--\n2024-10 | 6\n2024-11 | 4","lang":"sql"}]},{"b":["<code>CASE</code> adalah if-else di dalam SQL. Bentuknya <code>CASE WHEN kondisi THEN nilai ... ELSE nilai END</code>. Ia bisa dipakai di SELECT untuk membuat label, di ORDER BY untuk urutan khusus, bahkan di dalam SUM untuk menghitung bersyarat.","<code>COALESCE(a, b, c)</code> mengembalikan nilai pertama yang tidak NULL. Sangat berguna untuk memberi nilai cadangan: <code>COALESCE(kota, 'Belum diisi')</code>.","<code>NULLIF(a, b)</code> mengembalikan NULL jika a sama dengan b. Trik klasiknya mencegah pembagian dengan nol: <code>total / NULLIF(jumlah, 0)</code>."],"ex":[["Label dengan CASE","SELECT nama, harga,\n  CASE WHEN harga >= 75000 THEN 'premium'\n       WHEN harga >= 30000 THEN 'menengah'\n       ELSE 'hemat' END AS kelas\nFROM produk;"],["Menghitung bersyarat","SELECT COUNT(*) AS semua,\n  SUM(CASE WHEN status = 'selesai' THEN 1 ELSE 0 END) AS selesai,\n  SUM(CASE WHEN status = 'batal' THEN 1 ELSE 0 END) AS batal\nFROM pesanan;"],["COALESCE","SELECT nama, COALESCE(kota, 'Belum diisi') AS kota FROM pelanggan;"],["NULLIF mencegah bagi nol","SELECT nama, stok, harga / NULLIF(stok, 0) AS harga_per_stok FROM produk;"]],"task":{"q":"Tampilkan nama produk dan status stok (alias status_stok): 'habis' jika stok 0, 'menipis' jika stok di bawah 50, selain itu 'aman'.","a":"SELECT nama, CASE WHEN stok = 0 THEN 'habis' WHEN stok < 50 THEN 'menipis' ELSE 'aman' END AS status_stok FROM produk;"},"pts":["CASE WHEN ... THEN ... ELSE ... END.","Kondisi dicek berurutan; yang pertama benar dipakai.","COALESCE = nilai cadangan untuk NULL.","NULLIF(x, 0) mencegah pembagian dengan nol."],"q":[["<code>COALESCE(NULL, NULL, 'x', 'y')</code>?",["NULL","'x'","'y'"],1,"Nilai pertama yang tidak NULL."],["CASE tanpa ELSE dan tidak ada kondisi yang cocok menghasilkan?",["0","''","NULL"],2,"ELSE bawaan adalah NULL."]],"so":[{"q":"Kelompokkan karyawan: gaji &gt;= 15 juta \"Manajemen\", &gt;= 8 juta \"Senior\", selain itu \"Staf\". Hitung jumlah tiap kelompok.","h":"CASE di SELECT, lalu GROUP BY alias.","a":"SELECT CASE WHEN gaji >= 15000000 THEN 'Manajemen'\n            WHEN gaji >= 8000000 THEN 'Senior'\n            ELSE 'Staf' END AS kelompok,\n       COUNT(*) AS n\nFROM karyawan\nGROUP BY kelompok\nORDER BY n DESC;","out":"kelompok  | n\n----------+--\nManajemen | 3\nSenior    | 3\nStaf      | 2","lang":"sql"},{"q":"Tampilkan nama karyawan dan id atasannya; jika tidak punya atasan tulis 0.","h":"COALESCE(atasan_id, 0).","a":"SELECT nama, COALESCE(atasan_id, 0) AS atasan FROM karyawan;","out":"nama  | atasan\n------+-------\nSari  | 0\nTono  | 1\nUmi   | 1\nVino  | 2\nWati  | 2\nYudi  | 3\nZahra | 3\nRio   | 3","lang":"sql"}],"pro":[{"t":"Nilai cadangan untuk NULL","tag":"Lebih singkat","why":"<code>COALESCE</code> mengambil nilai pertama yang tidak NULL. Lebih pendek dari <code>CASE WHEN ... IS NULL</code>.","lang":"sql","a":"SELECT nama,\n       CASE WHEN kota IS NULL THEN 'Belum diisi' ELSE kota END AS kota\nFROM pelanggan\nORDER BY id\nLIMIT 4;","b":"SELECT nama, COALESCE(kota, 'Belum diisi') AS kota\nFROM pelanggan\nORDER BY id\nLIMIT 4;","out":"nama  | kota\n------+---------\nAndi  | Jakarta\nBudi  | Bandung\nCitra | Surabaya\nDewi  | Jakarta"}]},{"b":["Laporan untuk direksi harus rapi: label yang jelas dan tanpa nilai kosong."],"ex":[["Lihat pelanggan","SELECT * FROM pelanggan;"]],"tasks":[{"q":"Tampilkan nama produk dan label harga: 'Premium' jika harga ≥ 75000, 'Reguler' jika ≥ 25000, selain itu 'Hemat' (kolom label).","a":"SELECT nama, CASE WHEN harga >= 75000 THEN 'Premium' WHEN harga >= 25000 THEN 'Reguler' ELSE 'Hemat' END AS label FROM produk;"},{"q":"Tampilkan nama pelanggan dan kota; kota kosong diganti 'Belum diisi' (kolom kota).","a":"SELECT nama, COALESCE(kota, 'Belum diisi') AS kota FROM pelanggan;"},{"q":"Tampilkan nama pelanggan dalam huruf besar (kolom nama_besar) dan panjang namanya (kolom panjang).","a":"SELECT UPPER(nama) AS nama_besar, LENGTH(nama) AS panjang FROM pelanggan;"}],"pts":[],"q":[]},{"b":["<b>View</b> adalah query SELECT yang disimpan dengan sebuah nama, lalu dipakai seperti tabel. View tidak menyimpan data sendiri: setiap kali dipanggil, query aslinya dijalankan ulang, sehingga hasilnya selalu mengikuti data terbaru.","Kegunaannya: menyederhanakan query rumit yang sering dipakai (misalnya laporan penjualan dengan 4 JOIN), memberi nama yang bermakna, dan membatasi akses, misalnya tim marketing hanya diberi akses ke view tanpa kolom sensitif.","Buat dengan <code>CREATE VIEW</code>, ubah dengan <code>CREATE OR REPLACE VIEW</code> (PostgreSQL/MySQL) atau DROP lalu CREATE ulang, dan hapus dengan <code>DROP VIEW</code>. Menghapus view tidak menyentuh tabel aslinya."],"ex":[["Buat view laporan","CREATE VIEW v_penjualan AS\nSELECT s.id AS pesanan, p.nama AS pembeli, SUM(d.jumlah * pr.harga) AS total\nFROM pesanan s\nJOIN pelanggan p ON p.id = s.pelanggan_id\nJOIN detail_pesanan d ON d.pesanan_id = s.id\nJOIN produk pr ON pr.id = d.produk_id\nGROUP BY s.id, p.nama;\nSELECT * FROM v_penjualan WHERE total > 100000 ORDER BY total DESC;"],["View selalu mengikuti data terbaru","CREATE VIEW v_habis AS SELECT nama FROM produk WHERE stok = 0;\nUPDATE produk SET stok = 0 WHERE id = 6;\nSELECT * FROM v_habis;"],["Ubah lalu hapus","CREATE VIEW v_kota AS SELECT DISTINCT kota FROM pelanggan;\nCREATE OR REPLACE VIEW v_kota AS SELECT DISTINCT kota FROM pelanggan WHERE kota IS NOT NULL;\nSELECT * FROM v_kota;\nDROP VIEW v_kota;"]],"task":{"q":"Buat view bernama v_minuman berisi nama dan harga produk berkategori Minuman.","a":"CREATE VIEW v_minuman AS SELECT nama, harga FROM produk WHERE kategori = 'Minuman';","check":"SELECT * FROM v_minuman;"},"pts":["View = query bernama, dipakai seperti tabel.","Data tidak disalin; selalu terbaru.","Untuk menyederhanakan dan membatasi akses.","DROP VIEW tidak menghapus tabel."],"q":[["Data di view disimpan di mana?",["Di view itu sendiri","Tetap di tabel asal; view menjalankan ulang query","Di file terpisah"],1,"View hanyalah query tersimpan."],["Cara mengubah definisi view di PostgreSQL?",["ALTER VIEW SET","CREATE OR REPLACE VIEW","UPDATE VIEW"],1,"Definisi diganti dengan query baru."]],"so":[{"q":"Buat view v_ringkas_kategori berisi kategori, jumlah produk, dan total stok, lalu pakai untuk menampilkan kategori dengan stok di atas 100.","h":"CREATE VIEW ... AS SELECT ... GROUP BY.","a":"CREATE VIEW v_ringkas_kategori AS\nSELECT kategori, COUNT(*) AS n, SUM(stok) AS total_stok\nFROM produk\nGROUP BY kategori;\nSELECT * FROM v_ringkas_kategori WHERE total_stok > 100;","out":"kategori | n | total_stok\n---------+---+-----------\nMinuman  | 3 | 175\nCamilan  | 3 | 385","lang":"sql"},{"q":"Sebutkan tiga manfaat view.","h":"Penyederhanaan, keamanan, konsistensi.","a":"1. Menyederhanakan query rumit (JOIN panjang cukup ditulis sekali).\n2. Keamanan: pengguna diberi akses ke view tanpa kolom sensitif.\n3. Konsistensi: definisi metrik yang sama dipakai semua laporan.","lang":"text"}]},{"viz":"index","b":["Tanpa index, mencari pelanggan dari kota tertentu berarti database membaca <b>setiap baris</b> (full table scan). Untuk 10 juta baris, itu lambat. <b>Index</b> adalah struktur tambahan yang menyimpan nilai kolom secara terurut beserta penunjuk ke barisnya, seperti indeks di belakang buku. Database bisa langsung melompat ke lokasi yang tepat dengan pencarian biner.","Index mempercepat WHERE, JOIN, dan ORDER BY pada kolom yang diindeks, tetapi ada harganya: memakan ruang dan memperlambat INSERT, UPDATE, DELETE karena index juga harus diperbarui. Jadi buat index untuk kolom yang sering dicari, bukan untuk semua kolom.","Gunakan <code>EXPLAIN QUERY PLAN</code> (SQLite) atau <code>EXPLAIN</code> (PostgreSQL/MySQL) untuk melihat apakah database melakukan SCAN (baca semua) atau SEARCH (memakai index)."],"ex":[["Sebelum index: SCAN","EXPLAIN QUERY PLAN SELECT * FROM pelanggan WHERE kota = 'Jakarta';"],["Buat index lalu cek lagi","CREATE INDEX idx_pelanggan_kota ON pelanggan(kota);\nEXPLAIN QUERY PLAN SELECT * FROM pelanggan WHERE kota = 'Jakarta';"],["Primary key sudah terindeks","EXPLAIN QUERY PLAN SELECT * FROM produk WHERE id = 3;"],["UNIQUE index menolak duplikat","CREATE UNIQUE INDEX idx_produk_nama ON produk(nama);\nINSERT INTO produk (nama, kategori, harga) VALUES ('Kopi Gayo', 'Minuman', 1000);"],["Hapus index","CREATE INDEX idx_tmp ON pesanan(status);\nDROP INDEX idx_tmp;"]],"task":{"q":"Buat index bernama idx_pesanan_tanggal pada kolom tanggal di tabel pesanan.","a":"CREATE INDEX idx_pesanan_tanggal ON pesanan(tanggal);","check":"EXPLAIN QUERY PLAN SELECT * FROM pesanan WHERE tanggal = '2024-10-01';"},"pts":["Index = daftar terurut + penunjuk baris.","SCAN membaca semua; SEARCH memakai index.","Index mempercepat baca, memperlambat tulis.","Index kolom yang sering ada di WHERE dan JOIN."],"q":[["Kerugian membuat terlalu banyak index?",["Query SELECT lambat","INSERT/UPDATE lebih lambat dan butuh ruang","Data hilang"],1,"Setiap index ikut diperbarui saat data berubah."],["Perintah untuk melihat rencana eksekusi?",["SHOW PLAN","EXPLAIN","DESCRIBE"],1,"EXPLAIN menunjukkan cara database menjalankan query."]],"so":[{"q":"Buat index pada kolom kategori di tabel produk, lalu jalankan query yang memanfaatkannya.","h":"CREATE INDEX nama ON tabel(kolom).","a":"CREATE INDEX idx_produk_kategori ON produk(kategori);\nSELECT nama FROM produk WHERE kategori = 'Camilan';","out":"nama\n----------------\nKeripik Singkong\nKacang Mete\nKerupuk Udang","lang":"sql"},{"q":"Kapan index justru merugikan?","h":"Index harus ikut diperbarui setiap data berubah.","a":"Pada tabel yang sangat sering di-INSERT/UPDATE, index memperlambat penulisan.\nIndex pada kolom dengan sedikit nilai berbeda (misal jenis kelamin) jarang membantu,\ndan setiap index memakan ruang penyimpanan.","lang":"text"}]},{"viz":"txn","b":["Transfer Rp100.000 dari Andi ke Budi terdiri dari dua UPDATE: kurangi saldo Andi, tambah saldo Budi. Bagaimana jika listrik padam di antara keduanya? Uang hilang. <b>Transaksi</b> menyatukan beberapa perintah menjadi satu kesatuan: semua berhasil, atau tidak ada sama sekali.","Mulai dengan <code>BEGIN</code>. Perubahan setelahnya masih sementara. <code>COMMIT</code> menyimpannya secara permanen, sedangkan <code>ROLLBACK</code> membatalkan semuanya kembali ke kondisi sebelum BEGIN.","<code>SAVEPOINT nama</code> membuat titik simpan di tengah transaksi. <code>ROLLBACK TO nama</code> membatalkan hanya perubahan setelah titik itu, sementara transaksi tetap berjalan. Ikuti visualisasinya, lalu coba sendiri di editor."],"ex":[["Transfer yang di-COMMIT","BEGIN;\nUPDATE rekening SET saldo = saldo - 100000 WHERE id = 1;\nUPDATE rekening SET saldo = saldo + 100000 WHERE id = 2;\nCOMMIT;\nSELECT * FROM rekening;"],["Dibatalkan dengan ROLLBACK","BEGIN;\nUPDATE rekening SET saldo = 0;\nSELECT * FROM rekening;\nROLLBACK;\nSELECT * FROM rekening;"],["SAVEPOINT","BEGIN;\nUPDATE rekening SET saldo = saldo + 50000 WHERE id = 1;\nSAVEPOINT bonus;\nUPDATE rekening SET saldo = saldo + 999999 WHERE id = 2;\nROLLBACK TO bonus;\nCOMMIT;\nSELECT * FROM rekening;"]],"task":{"q":"Dalam satu transaksi, pindahkan saldo 50000 dari rekening 2 ke rekening 1, lalu COMMIT.","a":"BEGIN; UPDATE rekening SET saldo = saldo - 50000 WHERE id = 2; UPDATE rekening SET saldo = saldo + 50000 WHERE id = 1; COMMIT;","check":"SELECT id, saldo FROM rekening ORDER BY id;"},"pts":["BEGIN → perintah-perintah → COMMIT atau ROLLBACK.","Semua atau tidak sama sekali.","SAVEPOINT untuk membatalkan sebagian.","Di luar transaksi, setiap perintah otomatis di-commit (autocommit)."],"q":[["Perintah untuk membatalkan semua perubahan sejak BEGIN?",["COMMIT","ROLLBACK","UNDO"],1,"ROLLBACK kembali ke kondisi awal."],["Apa yang terjadi pada ROLLBACK TO savepoint?",["Transaksi selesai","Perubahan setelah savepoint dibatalkan, transaksi lanjut","Semua dibatalkan"],1,"Hanya sebagian yang dibatalkan."]],"so":[{"q":"Dalam transaksi, coba kurangi saldo Andi 600.000. Kenapa ditolak, dan apa yang harus dilakukan setelahnya?","h":"Saldo Andi hanya 500.000 dan CHECK (saldo &gt;= 0) menolak perubahan. Akhiri dengan ROLLBACK agar transaksi dibatalkan.","a":"BEGIN;\nUPDATE rekening SET saldo = saldo - 600000 WHERE id = 1;","out":"Galat: Nilai melanggar aturan CHECK pada kolom rekening.saldo.","lang":"sql"},{"q":"Transfer 100.000 dari Budi ke Andi dalam satu transaksi, lalu tampilkan saldo keduanya.","h":"BEGIN, dua UPDATE, COMMIT.","a":"BEGIN;\nUPDATE rekening SET saldo = saldo - 100000 WHERE id = 2;\nUPDATE rekening SET saldo = saldo + 100000 WHERE id = 1;\nCOMMIT;\nSELECT * FROM rekening;","out":"id | pemilik | saldo\n---+---------+-------\n1  | Andi    | 600000\n2  | Budi    | 200000","lang":"sql"}]},{"viz":"isolation","b":["Transaksi yang baik memenuhi <b>ACID</b>. <b>Atomicity</b>: semua atau tidak sama sekali. <b>Consistency</b>: data selalu berpindah dari keadaan valid ke keadaan valid, semua constraint terpenuhi. <b>Isolation</b>: transaksi yang berjalan bersamaan tidak saling mengacaukan. <b>Durability</b>: setelah COMMIT, data bertahan meski server mati.","Isolasi sempurna itu mahal, jadi database menawarkan beberapa <b>tingkat isolasi</b>. Dari yang paling longgar: <code>READ UNCOMMITTED</code> (bisa membaca data yang belum di-commit, disebut dirty read), <code>READ COMMITTED</code> (default PostgreSQL), <code>REPEATABLE READ</code> (default MySQL InnoDB), dan <code>SERIALIZABLE</code> (paling ketat, seolah transaksi berjalan bergiliran).","Semakin ketat, semakin sedikit anomali (dirty read, non-repeatable read, phantom read), tetapi semakin besar kemungkinan transaksi saling menunggu atau dibatalkan. Simulator ini berjalan untuk satu pengguna, jadi bagian ini dipelajari lewat visualisasi dan contoh sintaks."],"ex":[["Atomicity: satu gagal, semua batal","BEGIN;\nUPDATE rekening SET saldo = saldo + 100000 WHERE id = 2;\nUPDATE rekening SET saldo = saldo - 900000 WHERE id = 1;\n-- perintah kedua melanggar CHECK (saldo >= 0)\nROLLBACK;\nSELECT * FROM rekening;"]],"syn":["PostgreSQL / MySQL","-- PostgreSQL\nBEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;\nSELECT saldo FROM rekening WHERE id = 1;\nUPDATE rekening SET saldo = saldo - 100000 WHERE id = 1;\nCOMMIT;\n\n-- MySQL\nSET TRANSACTION ISOLATION LEVEL READ COMMITTED;\nSTART TRANSACTION;\n...\nCOMMIT;"],"pts":["ACID: Atomicity, Consistency, Isolation, Durability.","Empat tingkat isolasi: READ UNCOMMITTED → SERIALIZABLE.","Anomali: dirty read, non-repeatable read, phantom read.","Lebih ketat = lebih aman, tetapi lebih banyak saling tunggu."],"q":[["Huruf ACID yang menjamin data tetap ada setelah COMMIT walau server mati?",["Atomicity","Durability","Isolation"],1,"Durability = tahan lama."],["Membaca data transaksi lain yang belum di-commit disebut?",["Dirty read","Phantom read","Deadlock"],0,"Hanya terjadi di READ UNCOMMITTED."]],"so":[{"q":"Jelaskan A, C, I, D dengan contoh transfer bank.","h":"Atomicity, Consistency, Isolation, Durability.","a":"Atomicity  : debit dan kredit terjadi bersama atau tidak sama sekali.\nConsistency: total saldo tetap benar dan aturan (saldo >= 0) dijaga.\nIsolation  : transfer lain yang berjalan bersamaan tidak melihat keadaan setengah jadi.\nDurability : setelah COMMIT, hasil tetap ada walau server mati.","lang":"text"},{"q":"Pasangkan anomali dengan tingkat isolasi yang mencegahnya: dirty read, non-repeatable read, phantom read.","h":"READ COMMITTED, REPEATABLE READ, SERIALIZABLE.","a":"Dirty read            : dicegah mulai READ COMMITTED\nNon-repeatable read   : dicegah mulai REPEATABLE READ\nPhantom read          : dicegah SERIALIZABLE","lang":"text"}]},{"viz":"injection","b":["Prinsip <b>hak akses minimum</b> (least privilege): setiap pengguna dan aplikasi hanya diberi izin yang benar-benar diperlukan. <code>GRANT SELECT ON produk TO kasir</code> memberi izin membaca, <code>REVOKE</code> mencabutnya. Aplikasi web sebaiknya tidak memakai akun admin database.","Ancaman paling terkenal adalah <b>SQL injection</b>: input pengguna disambung langsung ke teks query, sehingga penyerang bisa menyisipkan perintah SQL sendiri. Input <code>' OR '1'='1</code> di form login bisa membuat kondisi WHERE selalu benar. Visualisasi di bawah memperlihatkan bagaimana query berubah.","Pertahanannya: <b>selalu pakai parameterized query / prepared statement</b> (tanda <code>?</code> atau <code>$1</code>), validasi input, batasi hak akses, enkripsi data sensitif, simpan password sebagai hash, dan cadangkan database secara rutin. Integritas data juga dijaga oleh constraint yang sudah kamu pelajari."],"ex":[["GRANT dan REVOKE (disimulasikan)","GRANT SELECT, INSERT ON pesanan TO kasir;\nREVOKE INSERT ON pesanan FROM kasir;"],["Inilah yang terjadi saat input disambung mentah-mentah","-- input pengguna: ' OR '1'='1\nSELECT * FROM pelanggan WHERE nama = '' OR '1'='1';"]],"syn":["Kode aplikasi: aman vs tidak aman","# TIDAK AMAN (Python): input disambung ke query\nq = \"SELECT * FROM pengguna WHERE email = '\" + email + \"'\"\ncursor.execute(q)\n\n# AMAN: parameterized query\ncursor.execute(\"SELECT * FROM pengguna WHERE email = %s\", (email,))\n\n// AMAN (Java JDBC)\nPreparedStatement ps = con.prepareStatement(\"SELECT * FROM pengguna WHERE email = ?\");\nps.setString(1, email);"],"pts":["Least privilege: beri izin seperlunya.","GRANT memberi, REVOKE mencabut.","Jangan pernah menyambung input ke query; pakai parameter.","Hash password, enkripsi data sensitif, backup rutin."],"q":[["Kenapa input <code>' OR '1'='1</code> berbahaya?",["Membuat database lambat","Mengubah logika WHERE menjadi selalu benar","Menghapus tabel otomatis"],1,"Penyerang mendapat semua baris."],["Pertahanan utama terhadap SQL injection?",["Menyembunyikan nama tabel","Parameterized query","Memakai huruf besar"],1,"Data dan perintah dikirim terpisah."]],"so":[{"q":"Tulis perintah untuk memberi role analis akses baca ke tabel produk dan pesanan, lalu mencabut akses ke pesanan.","h":"GRANT ... ON ... TO ...; REVOKE ... ON ... FROM ...;","a":"GRANT SELECT ON produk TO analis;\nGRANT SELECT ON pesanan TO analis;\nREVOKE SELECT ON pesanan FROM analis;","lang":"text"},{"q":"Input login berisi <code>' OR '1'='1</code>. Kenapa query yang dirangkai dengan string berbahaya, dan apa solusinya?","h":"Pakai parameter (prepared statement).","a":"Query menjadi: SELECT * FROM pengguna WHERE nama = '' OR '1'='1'\nKondisi selalu benar, sehingga semua baris lolos.\nSolusi: prepared statement / query berparameter, misalnya\nSELECT * FROM pengguna WHERE nama = ? dengan nilai dikirim terpisah.","lang":"text"}]},{"b":["<b>Stored procedure</b> adalah kumpulan perintah SQL yang disimpan di dalam database dengan sebuah nama, bisa menerima parameter, dan dipanggil dengan <code>CALL nama(...)</code>. <b>Function</b> mirip, tetapi mengembalikan nilai dan bisa dipakai di dalam SELECT.","Kelebihannya: logika yang dipakai banyak aplikasi tersimpan di satu tempat, lebih sedikit bolak-balik jaringan, dan hak akses bisa diberikan ke procedure tanpa membuka tabelnya. Kekurangannya: lebih sulit dites, di-version control, dan dipindah antar jenis database.","Sintaksnya sangat berbeda antar database (PL/pgSQL di PostgreSQL, T-SQL di SQL Server, dan versi MySQL). SQLite tidak punya stored procedure, sehingga bagian ini disajikan sebagai contoh untuk dibaca. Di simulator, kamu bisa meniru function sederhana memakai view atau ekspresi."],"ex":[["Meniru \"function\" dengan ekspresi di view","CREATE VIEW v_harga_pajak AS\nSELECT nama, harga, ROUND(harga * 1.11) AS harga_pajak FROM produk;\nSELECT * FROM v_harga_pajak WHERE harga_pajak > 50000;"],["Simulator menolak CREATE PROCEDURE","CREATE PROCEDURE tambah_stok() BEGIN END;"]],"syn":["PostgreSQL (function) & MySQL (procedure)","-- PostgreSQL: function yang mengembalikan nilai\nCREATE OR REPLACE FUNCTION harga_pajak(h INTEGER)\nRETURNS NUMERIC AS $$\nBEGIN\n  RETURN ROUND(h * 1.11);\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT nama, harga_pajak(harga) FROM produk;\n\n-- MySQL: procedure dengan parameter\nDELIMITER //\nCREATE PROCEDURE tambah_stok(IN pid INT, IN n INT)\nBEGIN\n  UPDATE produk SET stok = stok + n WHERE id = pid;\nEND //\nDELIMITER ;\n\nCALL tambah_stok(7, 20);"],"pts":["Procedure dipanggil dengan CALL; function dipakai di SELECT.","Logika terpusat di database.","Sulit dites dan tidak portabel antar database.","Sintaks berbeda tiap database."],"q":[["Cara memanggil stored procedure di MySQL?",["RUN nama()","CALL nama()","EXEC SELECT nama"],1,"CALL menjalankan procedure."],["Perbedaan utama function dengan procedure?",["Function mengembalikan nilai dan bisa dipakai di SELECT","Procedure lebih cepat","Tidak ada"],0,"Function berperilaku seperti ekspresi."]],"so":[{"q":"Tulis stored procedure PostgreSQL <code>tambah_stok(p_id, p_jumlah)</code> yang menambah stok produk.","h":"CREATE PROCEDURE ... LANGUAGE plpgsql AS $$ BEGIN ... END $$;","a":"CREATE PROCEDURE tambah_stok(p_id INT, p_jumlah INT)\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  UPDATE produk SET stok = stok + p_jumlah WHERE id = p_id;\nEND;\n$$;\n\nCALL tambah_stok(7, 25);","lang":"text"},{"q":"Kapan logika sebaiknya di stored procedure dan kapan di kode aplikasi?","h":"Pertimbangkan dekat-data, pengujian, dan portabilitas.","a":"Stored procedure: operasi berat dekat data, aturan yang harus sama untuk\nsemua aplikasi, mengurangi bolak-balik jaringan.\nKode aplikasi: logika bisnis yang sering berubah, mudah dites dan di-versioning,\ntidak terikat satu merek database.","lang":"text"}]},{"b":["Langkah pertama optimasi adalah <b>mengukur</b>, bukan menebak. Pakai <code>EXPLAIN</code> (atau <code>EXPLAIN ANALYZE</code> di PostgreSQL yang juga menjalankan query dan mencatat waktunya) untuk melihat bagian mana yang membaca banyak baris.","Teknik yang paling sering berdampak: <b>index</b> pada kolom di WHERE dan kondisi JOIN; <b>selective projection</b>, yaitu memilih kolom yang dibutuhkan saja, bukan <code>SELECT *</code>; <b>menyaring sedini mungkin</b> dengan WHERE; mengganti subquery berkorelasi yang berat dengan JOIN atau CTE; dan memakai <code>LIMIT</code> untuk tampilan berhalaman.","Hindari membungkus kolom berindeks dengan fungsi di WHERE, misalnya <code>WHERE UPPER(kota) = 'JAKARTA'</code>, karena index pada kota tidak bisa dipakai. Hindari juga <code>LIKE '%kata'</code> (wildcard di depan) untuk pencarian di tabel besar."],"ex":[["Index pada kolom JOIN","CREATE INDEX idx_pesanan_pelanggan ON pesanan(pelanggan_id);\nEXPLAIN QUERY PLAN\nSELECT p.nama, s.id FROM pelanggan p JOIN pesanan s ON s.pelanggan_id = p.id WHERE s.pelanggan_id = 1;"],["Fungsi di kolom mematikan index","CREATE INDEX idx_kota ON pelanggan(kota);\nEXPLAIN QUERY PLAN SELECT nama FROM pelanggan WHERE UPPER(kota) = 'JAKARTA';"],["Lebih baik: bandingkan kolom apa adanya","CREATE INDEX idx_kota ON pelanggan(kota);\nEXPLAIN QUERY PLAN SELECT nama FROM pelanggan WHERE kota = 'Jakarta';"],["Subquery berkorelasi ditulis ulang dengan JOIN + GROUP BY","SELECT p.nama, COUNT(s.id) AS banyak_pesanan\nFROM pelanggan p LEFT JOIN pesanan s ON s.pelanggan_id = p.id\nGROUP BY p.id, p.nama\nORDER BY banyak_pesanan DESC;"]],"task":{"q":"Tulis query efisien yang hanya mengambil kolom nama dan harga dari 3 produk termahal kategori Minuman.","a":"SELECT nama, harga FROM produk WHERE kategori = 'Minuman' ORDER BY harga DESC LIMIT 3;","order":true},"pts":["Ukur dengan EXPLAIN sebelum mengoptimasi.","Index kolom WHERE dan JOIN.","Pilih kolom seperlunya; saring sedini mungkin.","Jangan bungkus kolom berindeks dengan fungsi."],"q":[["Kenapa <code>WHERE UPPER(kota) = ...</code> bisa lambat?",["UPPER lambat sekali","Index pada kota tidak bisa dipakai","Error"],1,"Database harus menghitung UPPER untuk setiap baris."],["Arti selective projection?",["Memilih kolom yang dibutuhkan saja","Memilih tabel kecil","Memakai DISTINCT"],0,"Lebih sedikit data dibaca dan dikirim."]],"so":[{"q":"Tulis ulang query ini agar lebih efisien: <code>SELECT * FROM produk WHERE UPPER(kategori) = 'MINUMAN'</code>","h":"Ambil kolom yang perlu saja dan jangan bungkus kolom berindex dengan fungsi.","a":"SELECT nama, harga FROM produk WHERE kategori = 'Minuman';","out":"nama       | harga\n-----------+-------\nKopi Gayo  | 85000\nTeh Melati | 25000\nMadu Hutan | 120000","lang":"sql"},{"q":"Ganti subquery IN dengan EXISTS untuk mencari pelanggan yang pernah memesan.","h":"EXISTS berhenti begitu satu baris ditemukan.","a":"SELECT nama\nFROM pelanggan p\nWHERE EXISTS (SELECT 1 FROM pesanan s WHERE s.pelanggan_id = p.id)\nORDER BY nama;","out":"nama\n-----\nAndi\nBudi\nCitra\nDewi\nEko\nFitri\nHadi","lang":"sql"}]},{"b":["<b>CTE</b> (Common Table Expression) memberi nama pada sebuah query sementara dengan <code>WITH nama AS (SELECT ...)</code>, lalu nama itu bisa dipakai seperti tabel di query utama. CTE hanya hidup selama satu statement.","Kegunaan utamanya keterbacaan: query panjang dipecah menjadi langkah-langkah bernama yang dibaca dari atas ke bawah, seperti resep. Satu WITH bisa berisi beberapa CTE yang dipisah koma, dan CTE belakangan boleh memakai CTE sebelumnya.","Bandingkan dengan subquery bersarang yang harus dibaca dari dalam ke luar. CTE biasanya jauh lebih mudah dipahami, terutama oleh rekan tim."],"ex":[["Satu CTE","WITH total_per_pesanan AS (\n  SELECT pesanan_id, SUM(jumlah) AS item FROM detail_pesanan GROUP BY pesanan_id\n)\nSELECT * FROM total_per_pesanan WHERE item >= 5 ORDER BY item DESC;"],["Beberapa CTE berantai","WITH nilai AS (\n  SELECT s.pelanggan_id, SUM(d.jumlah * pr.harga) AS total\n  FROM pesanan s\n  JOIN detail_pesanan d ON d.pesanan_id = s.id\n  JOIN produk pr ON pr.id = d.produk_id\n  WHERE s.status <> 'batal'\n  GROUP BY s.pelanggan_id\n), rata AS (\n  SELECT AVG(total) AS r FROM nilai\n)\nSELECT p.nama, n.total\nFROM nilai n JOIN pelanggan p ON p.id = n.pelanggan_id, rata\nWHERE n.total > rata.r\nORDER BY n.total DESC;"]],"task":{"q":"Dengan CTE bernama stok_kategori yang berisi kategori dan SUM(stok) AS total, tampilkan kategori yang total stoknya di atas 100.","a":"WITH stok_kategori AS (SELECT kategori, SUM(stok) AS total FROM produk GROUP BY kategori) SELECT kategori, total FROM stok_kategori WHERE total > 100;"},"pts":["WITH nama AS (query) SELECT ... FROM nama.","Beberapa CTE dipisah koma.","CTE hanya berlaku untuk satu statement.","Pilih CTE demi keterbacaan."],"q":[["Berapa lama CTE hidup?",["Selamanya seperti tabel","Selama satu statement","Selama sesi"],1,"Berbeda dengan view yang tersimpan."],["Bolehkah CTE kedua memakai CTE pertama?",["Ya","Tidak","Hanya di PostgreSQL"],0,"Itulah keunggulan CTE berantai."]],"so":[{"q":"Dengan CTE, hitung total belanja per pesanan, lalu tampilkan pesanan yang totalnya di atas rata-rata semua pesanan.","h":"Dua CTE: total per pesanan, lalu bandingkan dengan AVG.","a":"WITH total AS (\n  SELECT d.pesanan_id, SUM(d.jumlah * pr.harga) AS belanja\n  FROM detail_pesanan d\n  JOIN produk pr ON pr.id = d.produk_id\n  GROUP BY d.pesanan_id\n)\nSELECT pesanan_id, belanja\nFROM total\nWHERE belanja > (SELECT AVG(belanja) FROM total)\nORDER BY belanja DESC;","out":"pesanan_id | belanja\n-----------+--------\n101        | 245000\n108        | 205000\n106        | 200000\n107        | 200000\n104        | 195000\n109        | 180000","lang":"sql"},{"q":"Dengan CTE, hitung jumlah karyawan per divisi lalu tampilkan divisi terbesar saja.","h":"CTE lalu ORDER BY ... LIMIT 1.","a":"WITH per_divisi AS (\n  SELECT divisi, COUNT(*) AS n FROM karyawan GROUP BY divisi\n)\nSELECT divisi, n FROM per_divisi ORDER BY n DESC LIMIT 1;","out":"divisi    | n\n----------+--\nPenjualan | 4","lang":"sql"}],"pro":[{"t":"Beri nama pada subquery dengan WITH","tag":"Lebih mudah dibaca","why":"Subquery bertingkat dibaca dari dalam ke luar. CTE dibaca dari atas ke bawah seperti langkah-langkah, dan setiap langkah punya nama.","lang":"sql","a":"SELECT p.nama, t.total\nFROM (\n  SELECT pelanggan_id, COUNT(*) AS total\n  FROM pesanan\n  GROUP BY pelanggan_id\n) AS t\nJOIN pelanggan p ON p.id = t.pelanggan_id\nWHERE t.total >= 2\nORDER BY t.total DESC, p.nama;","b":"WITH jumlah_pesanan AS (\n  SELECT pelanggan_id, COUNT(*) AS total\n  FROM pesanan\n  GROUP BY pelanggan_id\n)\nSELECT p.nama, j.total\nFROM jumlah_pesanan j\nJOIN pelanggan p ON p.id = j.pelanggan_id\nWHERE j.total >= 2\nORDER BY j.total DESC, p.nama;","out":"nama | total\n-----+------\nAndi | 3\nBudi | 2"}]},{"viz":"recursive","b":["<code>WITH RECURSIVE</code> membuat CTE yang memanggil dirinya sendiri, cocok untuk data berbentuk hierarki atau pohon: struktur organisasi, kategori bertingkat, atau rute.","Bentuknya selalu dua bagian yang digabung <code>UNION ALL</code>. <b>Anchor</b> adalah titik awal (misalnya direktur yang tidak punya atasan). <b>Bagian rekursif</b> men-JOIN tabel dengan hasil putaran sebelumnya untuk menemukan tingkat berikutnya. Proses berulang sampai putaran baru tidak menghasilkan baris lagi.","Pastikan ada kondisi berhenti. Tanpa itu, rekursi bisa berjalan tanpa akhir; simulator ini menghentikannya setelah 1000 putaran."],"ex":[["Deret angka 1 sampai 10","WITH RECURSIVE angka(n) AS (\n  SELECT 1\n  UNION ALL\n  SELECT n + 1 FROM angka WHERE n < 10\n)\nSELECT n FROM angka;"],["Struktur organisasi","WITH RECURSIVE bagan AS (\n  SELECT id, nama, jabatan, 0 AS tingkat, nama AS jalur\n  FROM karyawan WHERE atasan_id IS NULL\n  UNION ALL\n  SELECT k.id, k.nama, k.jabatan, b.tingkat + 1, b.jalur || ' > ' || k.nama\n  FROM karyawan k JOIN bagan b ON k.atasan_id = b.id\n)\nSELECT tingkat, nama, jabatan, jalur FROM bagan ORDER BY jalur;"],["Kalender 7 hari","WITH RECURSIVE hari(t) AS (\n  SELECT '2024-11-01'\n  UNION ALL\n  SELECT DATE(t, '+1 day') FROM hari WHERE t < '2024-11-07'\n)\nSELECT t, STRFTIME('%w', t) AS hari_ke FROM hari;"]],"task":{"q":"Dengan WITH RECURSIVE, tampilkan nama semua bawahan (langsung maupun tidak langsung) dari Umi (id 3). Satu kolom: nama.","a":"WITH RECURSIVE bawahan AS (SELECT id, nama FROM karyawan WHERE atasan_id = 3 UNION ALL SELECT k.id, k.nama FROM karyawan k JOIN bawahan b ON k.atasan_id = b.id) SELECT nama FROM bawahan;"},"pts":["Anchor UNION ALL bagian rekursif.","Bagian rekursif men-JOIN hasil putaran sebelumnya.","Berhenti saat putaran tidak menghasilkan baris.","Cocok untuk pohon dan hierarki."],"q":[["Bagian yang dijalankan sekali di awal CTE rekursif?",["Anchor","Bagian rekursif","UNION"],0,"Anchor adalah titik awal."],["Kapan rekursi berhenti?",["Setelah 10 putaran","Saat putaran baru tidak menghasilkan baris","Tidak pernah"],1,"Itulah kondisi berhentinya."]],"so":[{"q":"Dengan WITH RECURSIVE, buat deret angka 1 sampai 5 beserta kuadratnya.","h":"Anchor SELECT 1, lalu UNION ALL n + 1 sampai batas.","a":"WITH RECURSIVE angka(n) AS (\n  SELECT 1\n  UNION ALL\n  SELECT n + 1 FROM angka WHERE n < 5\n)\nSELECT n, n * n AS kuadrat FROM angka;","out":"n | kuadrat\n--+--------\n1 | 1\n2 | 4\n3 | 9\n4 | 16\n5 | 25","lang":"sql"},{"q":"Tampilkan rantai atasan untuk Vino sampai direktur.","h":"Mulai dari Vino, lalu naik lewat atasan_id.","a":"WITH RECURSIVE rantai AS (\n  SELECT id, nama, atasan_id, 0 AS naik FROM karyawan WHERE nama = 'Vino'\n  UNION ALL\n  SELECT k.id, k.nama, k.atasan_id, r.naik + 1\n  FROM karyawan k JOIN rantai r ON k.id = r.atasan_id\n)\nSELECT naik, nama FROM rantai ORDER BY naik;","out":"naik | nama\n-----+-----\n0    | Vino\n1    | Tono\n2    | Sari","lang":"sql"}]},{"viz":"window","b":["<b>Window function</b> menghitung nilai berdasarkan sekelompok baris yang berkaitan, tetapi <i>tidak</i> menggabungkan baris seperti GROUP BY. Setiap baris tetap muncul, dengan kolom tambahan hasil perhitungan. Sintaksnya: <code>fungsi() OVER (PARTITION BY ... ORDER BY ...)</code>.","<code>PARTITION BY</code> membagi baris menjadi kelompok (jendela), dan <code>ORDER BY</code> di dalam OVER menentukan urutan di setiap kelompok. <code>ROW_NUMBER</code> memberi nomor urut 1, 2, 3 tanpa kembar. <code>RANK</code> memberi peringkat yang sama untuk nilai sama lalu melompat (1, 1, 3). <code>DENSE_RANK</code> tidak melompat (1, 1, 2).","Pola terkenal: \"ambil N teratas per kelompok\", misalnya produk termahal di setiap kategori. Hitung ROW_NUMBER per kategori di CTE, lalu saring nomor 1."],"ex":[["Peringkat harga dalam kategori","SELECT nama, kategori, harga,\n  ROW_NUMBER() OVER (PARTITION BY kategori ORDER BY harga DESC) AS no,\n  RANK() OVER (PARTITION BY kategori ORDER BY harga DESC) AS peringkat\nFROM produk;"],["RANK vs DENSE_RANK pada nilai kembar","SELECT pesanan_id, produk_id, jumlah,\n  RANK() OVER (ORDER BY jumlah DESC) AS rank_,\n  DENSE_RANK() OVER (ORDER BY jumlah DESC) AS dense\nFROM detail_pesanan;"],["Termahal per kategori","WITH urut AS (\n  SELECT nama, kategori, harga,\n         ROW_NUMBER() OVER (PARTITION BY kategori ORDER BY harga DESC) AS no\n  FROM produk\n)\nSELECT kategori, nama, harga FROM urut WHERE no = 1;"]],"task":{"q":"Tampilkan nama karyawan, divisi, gaji, dan peringkat gaji di divisinya (alias peringkat, pakai DENSE_RANK, gaji tertinggi = 1).","a":"SELECT nama, divisi, gaji, DENSE_RANK() OVER (PARTITION BY divisi ORDER BY gaji DESC) AS peringkat FROM karyawan;"},"pts":["Window function tidak mengurangi jumlah baris.","OVER (PARTITION BY ... ORDER BY ...).","ROW_NUMBER unik; RANK melompat; DENSE_RANK rapat.","Top-N per kelompok: ROW_NUMBER di CTE, lalu WHERE no &lt;= N."],"q":[["Nilai 100, 100, 90 dengan RANK menghasilkan?",["1, 2, 3","1, 1, 3","1, 1, 2"],1,"RANK melompat setelah nilai kembar."],["Perbedaan GROUP BY dengan window function?",["GROUP BY menggabungkan baris; window tetap mempertahankan setiap baris","Tidak ada","Window lebih lambat selalu"],0,"Window menambah kolom tanpa menghilangkan baris."]],"so":[{"q":"Tampilkan karyawan dengan gaji tertinggi di setiap divisi memakai ROW_NUMBER.","h":"PARTITION BY divisi ORDER BY gaji DESC, lalu ambil no = 1.","a":"WITH urut AS (\n  SELECT nama, divisi, gaji,\n         ROW_NUMBER() OVER (PARTITION BY divisi ORDER BY gaji DESC) AS no\n  FROM karyawan\n)\nSELECT divisi, nama, gaji FROM urut WHERE no = 1 ORDER BY divisi;","out":"divisi    | nama | gaji\n----------+------+---------\nGudang    | Tono | 15000000\nPenjualan | Umi  | 16000000\nPusat     | Sari | 30000000","lang":"sql"},{"q":"Tampilkan gaji semua karyawan beserta RANK dan DENSE_RANK. Kenapa angkanya berbeda setelah ada gaji yang sama?","h":"Nilai yang sama mendapat peringkat sama; RANK melompati angka berikutnya.","a":"SELECT nama, gaji,\n  RANK() OVER (ORDER BY gaji DESC) AS rnk,\n  DENSE_RANK() OVER (ORDER BY gaji DESC) AS dense\nFROM karyawan\nORDER BY rnk, nama;","out":"nama  | gaji     | rnk | dense\n------+----------+-----+------\nSari  | 30000000 | 1   | 1\nUmi   | 16000000 | 2   | 2\nTono  | 15000000 | 3   | 3\nZahra | 8500000  | 4   | 4\nRio   | 8000000  | 5   | 5\nYudi  | 8000000  | 5   | 5\nWati  | 7500000  | 7   | 6\nVino  | 7000000  | 8   | 7","lang":"sql"}],"pro":[{"t":"Peringkat tanpa subquery berkorelasi","tag":"Lebih cepat","why":"Subquery berkorelasi dijalankan ulang untuk setiap baris. Window function menghitung peringkat semua baris dalam satu kali jalan.","lang":"sql","a":"SELECT nama, harga,\n       (SELECT COUNT(*) FROM produk p2 WHERE p2.harga > p1.harga) + 1 AS peringkat\nFROM produk p1\nORDER BY peringkat\nLIMIT 4;","b":"SELECT nama, harga,\n       RANK() OVER (ORDER BY harga DESC) AS peringkat\nFROM produk\nORDER BY peringkat\nLIMIT 4;","out":"nama           | harga  | peringkat\n---------------+--------+----------\nMadu Hutan     | 120000 | 1\nKopi Gayo      | 85000  | 2\nRendang Kaleng | 75000  | 3\nKacang Mete    | 60000  | 4"}]},{"viz":"window","b":["<code>LAG(kolom)</code> mengambil nilai dari baris <i>sebelumnya</i> di jendela, dan <code>LEAD(kolom)</code> dari baris <i>berikutnya</i>. Keduanya sangat berguna untuk membandingkan baris dengan tetangganya: selisih penjualan bulan ini dengan bulan lalu, atau jarak hari antarpesanan.","Parameter kedua adalah jarak (default 1), dan parameter ketiga nilai cadangan jika tidak ada baris tetangga: <code>LAG(harga, 1, 0)</code>.","Fungsi agregat juga bisa dipakai sebagai window function. <code>SUM(x) OVER (ORDER BY tanggal)</code> menghasilkan <b>running total</b> (total berjalan), dan dengan PARTITION BY total berjalan dihitung ulang untuk setiap kelompok."],"ex":[["Pesanan sebelumnya & berikutnya","SELECT id, tanggal,\n  LAG(tanggal) OVER (ORDER BY tanggal) AS sebelumnya,\n  LEAD(tanggal) OVER (ORDER BY tanggal) AS berikutnya\nFROM pesanan;"],["Jarak hari dari pesanan sebelumnya per pelanggan","SELECT pelanggan_id, id, tanggal,\n  JULIANDAY(tanggal) - JULIANDAY(LAG(tanggal) OVER (PARTITION BY pelanggan_id ORDER BY tanggal)) AS jarak_hari\nFROM pesanan ORDER BY pelanggan_id, tanggal;"],["Running total item terjual","SELECT s.tanggal, SUM(d.jumlah) AS item,\n  SUM(SUM(d.jumlah)) OVER (ORDER BY s.tanggal) AS kumulatif\nFROM pesanan s JOIN detail_pesanan d ON d.pesanan_id = s.id\nGROUP BY s.tanggal ORDER BY s.tanggal;"]],"task":{"q":"Tampilkan id, tanggal, dan id pesanan sebelumnya (alias id_sebelumnya, pakai LAG dengan nilai cadangan 0) dari tabel pesanan, urut berdasarkan tanggal.","a":"SELECT id, tanggal, LAG(id, 1, 0) OVER (ORDER BY tanggal) AS id_sebelumnya FROM pesanan ORDER BY tanggal;","order":true},"pts":["LAG = baris sebelumnya, LEAD = baris berikutnya.","LAG(kolom, jarak, cadangan).","SUM(...) OVER (ORDER BY ...) = running total.","PARTITION BY untuk menghitung ulang per kelompok."],"q":[["Nilai LAG(x) pada baris pertama tanpa cadangan?",["0","NULL","Nilai baris terakhir"],1,"Tidak ada baris sebelumnya."],["Fungsi untuk total berjalan?",["SUM(x) OVER (ORDER BY ...)","RUNNING(x)","COUNT(*)"],0,"Agregat sebagai window function."]],"so":[{"q":"Tampilkan gaji karyawan divisi Penjualan urut dari kecil, beserta total kumulatifnya.","h":"SUM(gaji) OVER (ORDER BY ...).","a":"SELECT nama, gaji,\n  SUM(gaji) OVER (ORDER BY gaji, nama) AS kumulatif\nFROM karyawan\nWHERE divisi = 'Penjualan'\nORDER BY gaji, nama;","out":"nama  | gaji     | kumulatif\n------+----------+----------\nRio   | 8000000  | 8000000\nYudi  | 8000000  | 16000000\nZahra | 8500000  | 24500000\nUmi   | 16000000 | 40500000","lang":"sql"},{"q":"Tampilkan produk urut harga, beserta harga produk berikutnya yang lebih mahal dan selisihnya.","h":"LEAD(harga) OVER (ORDER BY harga).","a":"SELECT nama, harga,\n  LEAD(harga) OVER (ORDER BY harga) AS berikutnya,\n  LEAD(harga) OVER (ORDER BY harga) - harga AS selisih\nFROM produk\nORDER BY harga;","out":"nama             | harga  | berikutnya | selisih\n-----------------+--------+------------+--------\nKeripik Singkong | 15000  | 20000      | 5000\nKerupuk Udang    | 20000  | 25000      | 5000\nTeh Melati       | 25000  | 30000      | 5000\nSambal Bawang    | 30000  | 60000      | 30000\nKacang Mete      | 60000  | 75000      | 15000\nRendang Kaleng   | 75000  | 85000      | 10000\nKopi Gayo        | 85000  | 120000     | 35000\nMadu Hutan       | 120000 | NULL       | NULL","lang":"sql"}]},{"b":["<b>Pivot</b> memutar baris menjadi kolom, misalnya dari daftar \"status per pesanan\" menjadi satu baris berisi jumlah pesanan baru, dikirim, selesai, dan batal. SQL Server dan Oracle punya operator <code>PIVOT</code>, tetapi cara yang bekerja di semua database adalah agregasi bersyarat: <code>SUM(CASE WHEN ... THEN 1 ELSE 0 END)</code> untuk setiap kolom.","<b>Unpivot</b> adalah kebalikannya: kolom-kolom diubah menjadi baris, biasanya dengan beberapa SELECT yang digabung <code>UNION ALL</code>.","<b>Dynamic SQL</b> adalah query yang teksnya disusun saat program berjalan, misalnya ketika daftar kolom pivot baru diketahui saat itu. Ia dijalankan dengan <code>EXECUTE</code> (PostgreSQL), <code>sp_executesql</code> (SQL Server), atau <code>PREPARE</code> (MySQL). Dynamic SQL sangat rawan SQL injection, jadi nilai dari pengguna wajib dikirim sebagai parameter, dan nama kolom atau tabel harus divalidasi terhadap daftar yang diizinkan."],"ex":[["Pivot: status pesanan menjadi kolom","SELECT\n  SUM(CASE WHEN status = 'baru' THEN 1 ELSE 0 END) AS baru,\n  SUM(CASE WHEN status = 'dikirim' THEN 1 ELSE 0 END) AS dikirim,\n  SUM(CASE WHEN status = 'selesai' THEN 1 ELSE 0 END) AS selesai,\n  SUM(CASE WHEN status = 'batal' THEN 1 ELSE 0 END) AS batal\nFROM pesanan;"],["Pivot per bulan","SELECT strftime('%Y-%m', tanggal) AS bulan,\n  SUM(CASE WHEN status = 'selesai' THEN 1 ELSE 0 END) AS selesai,\n  SUM(CASE WHEN status <> 'selesai' THEN 1 ELSE 0 END) AS lainnya\nFROM pesanan GROUP BY bulan;"],["Unpivot: kolom menjadi baris","SELECT nama, 'harga' AS atribut, harga AS nilai FROM produk WHERE id = 1\nUNION ALL\nSELECT nama, 'stok', stok FROM produk WHERE id = 1;"]],"syn":["SQL Server: PIVOT & dynamic SQL","-- Operator PIVOT\nSELECT * FROM (SELECT status, id FROM pesanan) AS src\nPIVOT (COUNT(id) FOR status IN ([baru], [dikirim], [selesai], [batal])) AS p;\n\n-- Dynamic SQL dengan parameter (aman)\nDECLARE @sql NVARCHAR(200) = N'SELECT nama FROM produk WHERE kategori = @kat';\nEXEC sp_executesql @sql, N'@kat NVARCHAR(50)', @kat = N'Minuman';"],"task":{"q":"Buat pivot dari tabel produk: satu baris dengan kolom minuman, camilan, dan lainnya berisi jumlah produk di setiap kelompok (lainnya = selain Minuman dan Camilan).","a":"SELECT SUM(CASE WHEN kategori = 'Minuman' THEN 1 ELSE 0 END) AS minuman, SUM(CASE WHEN kategori = 'Camilan' THEN 1 ELSE 0 END) AS camilan, SUM(CASE WHEN kategori NOT IN ('Minuman','Camilan') THEN 1 ELSE 0 END) AS lainnya FROM produk;"},"pts":["Pivot portabel: SUM(CASE WHEN ...) per kolom.","Unpivot: UNION ALL beberapa SELECT.","Dynamic SQL = teks query disusun saat runtime.","Dynamic SQL wajib memakai parameter dan whitelist."],"q":[["Cara pivot yang bekerja di hampir semua database?",["Operator PIVOT","Agregasi dengan CASE WHEN","JOIN"],1,"PIVOT hanya ada di beberapa database."],["Risiko terbesar dynamic SQL?",["Lambat","SQL injection","Tidak bisa ORDER BY"],1,"Teks query disusun dari input."]],"so":[{"q":"Buat pivot jumlah karyawan per divisi menjadi satu baris (kolom gudang, penjualan, pusat).","h":"SUM(CASE WHEN divisi = ... THEN 1 ELSE 0 END).","a":"SELECT\n  SUM(CASE WHEN divisi = 'Gudang' THEN 1 ELSE 0 END) AS gudang,\n  SUM(CASE WHEN divisi = 'Penjualan' THEN 1 ELSE 0 END) AS penjualan,\n  SUM(CASE WHEN divisi = 'Pusat' THEN 1 ELSE 0 END) AS pusat\nFROM karyawan;","out":"gudang | penjualan | pusat\n-------+-----------+------\n3      | 4         | 1","lang":"sql"},{"q":"Unpivot data Madu Hutan: ubah kolom harga dan stok menjadi baris (atribut, nilai).","h":"Dua SELECT digabung UNION ALL.","a":"SELECT nama, 'harga' AS atribut, harga AS nilai FROM produk WHERE nama = 'Madu Hutan'\nUNION ALL\nSELECT nama, 'stok', stok FROM produk WHERE nama = 'Madu Hutan';","out":"nama       | atribut | nilai\n-----------+---------+-------\nMadu Hutan | harga   | 120000\nMadu Hutan | stok    | 15","lang":"sql"}]},{"b":["Analisis lanjutan dengan CTE dan window function."],"ex":[["Lihat produk","SELECT * FROM produk;"]],"tasks":[{"q":"Beri peringkat produk dalam setiap kategori berdasarkan harga tertinggi (kolom peringkat, pakai RANK). Tampilkan kategori, nama, harga, peringkat.","a":"SELECT kategori, nama, harga, RANK() OVER (PARTITION BY kategori ORDER BY harga DESC) AS peringkat FROM produk;"},{"q":"Dengan CTE, hitung jumlah pesanan per pelanggan (kolom n) lalu tampilkan hanya pelanggan dengan n ≥ 2 beserta namanya.","a":"WITH hitung AS (SELECT pelanggan_id, COUNT(*) AS n FROM pesanan GROUP BY pelanggan_id) SELECT p.nama, h.n FROM hitung h JOIN pelanggan p ON p.id = h.pelanggan_id WHERE h.n >= 2;"},{"q":"Tampilkan id pesanan, tanggal, dan tanggal pesanan sebelumnya (kolom sebelumnya) memakai LAG, urut tanggal lalu id.","a":"SELECT id, tanggal, LAG(tanggal) OVER (ORDER BY tanggal, id) AS sebelumnya FROM pesanan ORDER BY tanggal, id;","order":true}],"pts":[],"q":[]},{"stack":"SQL (PostgreSQL/SQLite)","brief":"Rancang database toko buku \"Pustaka Nusantara\": buku, penulis, pelanggan, pesanan. Isi data contoh, lalu jawab pertanyaan bisnis dengan query.","feats":["Diagram ERD dengan relasi banyak-ke-banyak buku-penulis","CREATE TABLE dengan PRIMARY KEY, FOREIGN KEY, CHECK, NOT NULL","Minimal 20 buku, 10 penulis, 15 pelanggan, 40 pesanan","Index untuk kolom yang sering dicari","View laporan_penjualan_bulanan","Transaksi pemesanan yang mengurangi stok secara atomik","Query: 5 penulis terlaris, pelanggan tanpa pesanan 90 hari, pertumbuhan MoM","Window function untuk peringkat buku per genre"],"steps":["Rancang ERD dan normalisasi sampai 3NF.","Tulis DDL dan data contoh.","Tambah index, view, dan transaksi.","Jawab pertanyaan bisnis."],"files":[["skema.sql","sql","CREATE TABLE penulis (id INTEGER PRIMARY KEY, nama TEXT NOT NULL);\nCREATE TABLE buku (\n  id INTEGER PRIMARY KEY,\n  judul TEXT NOT NULL,\n  genre TEXT,\n  harga INTEGER CHECK (harga > 0),\n  stok INTEGER NOT NULL DEFAULT 0 CHECK (stok >= 0)\n);\nCREATE TABLE buku_penulis (\n  buku_id INTEGER REFERENCES buku(id),\n  penulis_id INTEGER REFERENCES penulis(id),\n  PRIMARY KEY (buku_id, penulis_id)\n);\nINSERT INTO penulis VALUES (1,'Andrea Hirata'),(2,'Dee Lestari'),(3,'Tere Liye');\nINSERT INTO buku VALUES (1,'Laskar Pelangi','Novel',89000,12),(2,'Supernova','Novel',99000,5),(3,'Hujan','Novel',95000,0);\nINSERT INTO buku_penulis VALUES (1,1),(2,2),(3,3);\nSELECT b.judul, p.nama, b.stok FROM buku b\nJOIN buku_penulis bp ON bp.buku_id = b.id\nJOIN penulis p ON p.id = bp.penulis_id\nORDER BY b.judul;"]],"sql":{"db":"kosong","file":0}}]);
